// Offline automated test for the C module (offline crash dump analysis).
//
// Coverage IDs: C-02 C-03 C-04 C-05 C-06 C-07 C-08 C-09 C-10.
// C-01 (DbgEng probe) and comparison with real dump/WinDbg are not here — that requires real samples and a debugging engine.
//
// Assertion principle (Q-01 red line: tests must not self-verify):
//   * The dumped bytes are generated by this file with manually written offsets based on the **public layout** of DUMP_HEADER64. In
//     production code, all offset constants reside in an anonymous namespace, so tests cannot access them; any offset error will be exposed.
//   * Expected values are always hardcoded independently (listing escaped strings byte-by-byte, counting
//     fields manually); do not treat the output of production functions as 'the other side' input;
//   * Every branch of each enumeration must be covered; no branch may have zero coverage.
//   * "Default construction" must be tested separately: the default state must be unknown/untrusted/rejected, never complete/safe/allowed.

#include "TestSupport.h"

#include "../../../shared/evidence/DumpFacts.h"

#include <chrono>
#include <cstdint>
#include <string>
#include <vector>

namespace {

using namespace ksword::evidence;

// ---------------------------------------------------------------------------
// Reporter: Local forwarder for ksword_tests::Suite. Counts still go entirely through the real
// Suite; this only does one extra thing — fix wide-character streams broken by Chinese suite names.
//
// Why it is needed (based on actual measurements, not speculation): Non-ASCII wide characters in the suite name L"C Offline Crash Dump
// Analysis" cannot be converted to narrow characters by wcout/wcerr under the default "C" locale, causing MSVC to set badbit at that location.
// **Suppress all subsequent output**. After injecting a real defect and testing: 3 assertions failed, but the console only showed one truncated
// line "FAIL [C", and the labels for the other two failures were lost — the failure count matches, but no one knows where the errors are.
// Clear the stream state after each assertion and append a line of pure ASCII full tags on failure to enable debugging.
// ---------------------------------------------------------------------------
class Reporter final {
public:
    explicit Reporter(ksword_tests::Suite& suite) : suite_(suite) {}

    void expect(bool condition, const wchar_t* label) {
        const int kBefore = suite_.failures();
        suite_.expect(condition, label);
        // The suite name has been changed to pure ASCII, so wide streams will no longer be swallowed due to conversion failures;
        // Suite in TestSupport.h also clears stream state after each output. Duplicate FAIL lines are no longer printed here.
        (void)kBefore;
    }

private:
    ksword_tests::Suite& suite_;
};

// ---------------------------------------------------------------------------
// Byte construction utility. Entirely in the test side; offsets are written by the tests themselves.
// ---------------------------------------------------------------------------
void putU32(std::vector<std::uint8_t>& buffer, std::size_t offset, std::uint32_t value) {
    buffer[offset + 0] = static_cast<std::uint8_t>(value & 0xFFU);
    buffer[offset + 1] = static_cast<std::uint8_t>((value >> 8) & 0xFFU);
    buffer[offset + 2] = static_cast<std::uint8_t>((value >> 16) & 0xFFU);
    buffer[offset + 3] = static_cast<std::uint8_t>((value >> 24) & 0xFFU);
}

void putU64(std::vector<std::uint8_t>& buffer, std::size_t offset, std::uint64_t value) {
    putU32(buffer, offset, static_cast<std::uint32_t>(value & 0xFFFFFFFFULL));
    putU32(buffer, offset + 4, static_cast<std::uint32_t>((value >> 32) & 0xFFFFFFFFULL));
}

void putAscii(std::vector<std::uint8_t>& buffer, std::size_t offset, const char* text) {
    for (std::size_t index = 0; text[index] != '\0'; ++index) {
        buffer[offset + index] = static_cast<std::uint8_t>(text[index]);
    }
}

std::span<const std::uint8_t> view(const std::vector<std::uint8_t>& buffer) {
    return std::span<const std::uint8_t>(buffer.data(), buffer.size());
}

// Manually written DUMP_HEADER64 values. The test later compares these constants field-by-field, rather than deriving them from production code.
constexpr std::uint32_t kFixtureMajorVersion = 15U;
constexpr std::uint32_t kFixtureBuildNumber = 26100U;
constexpr std::uint32_t kFixtureProcessorCount = 16U;
constexpr std::uint32_t kFixtureBugCheckCode = 0x0000007EU;
constexpr std::uint64_t kFixtureParam0 = 0xFFFFFFFFC0000005ULL;
constexpr std::uint64_t kFixtureParam1 = 0xFFFFF80312345678ULL;
constexpr std::uint64_t kFixtureParam2 = 0x0000000000000000ULL;  // Truly 0, not missing.
constexpr std::uint64_t kFixtureParam3 = 0xFFFFF8031234ABCDULL;
constexpr std::uint64_t kFixtureCrashTime = 0x01DA1234ABCD0000ULL;
constexpr std::uint64_t kFixtureUptime = 0x0000000E4E1C0000ULL;
constexpr std::uint64_t kFixtureDirectoryTableBase = 0x00000000001AA000ULL;

// makeKernelHeader: a 0x2000-byte PAGEDU64 header.
// All offsets are manually written according to the official DUMP_HEADER64 layout.
std::vector<std::uint8_t> makeKernelHeader(std::uint32_t dumpType, std::uint32_t machineType) {
    std::vector<std::uint8_t> buffer(0x2000, 0U);
    putAscii(buffer, 0x00, "PAGE");
    putAscii(buffer, 0x04, "DU64");
    putU32(buffer, 0x08, kFixtureMajorVersion);
    putU32(buffer, 0x0C, kFixtureBuildNumber);
    putU64(buffer, 0x10, kFixtureDirectoryTableBase);
    putU32(buffer, 0x30, machineType);
    putU32(buffer, 0x34, kFixtureProcessorCount);
    putU32(buffer, 0x38, kFixtureBugCheckCode);
    putU64(buffer, 0x40, kFixtureParam0);
    putU64(buffer, 0x48, kFixtureParam1);
    putU64(buffer, 0x50, kFixtureParam2);
    putU64(buffer, 0x58, kFixtureParam3);
    putU32(buffer, 0xF98, dumpType);
    putU64(buffer, 0xFA8, kFixtureCrashTime);
    putU64(buffer, 0x1030, kFixtureUptime);
    putU32(buffer, 0x1048, 0U);  // WriterStatus = 0: This indicates 'write normal', not a missing state.
    return buffer;
}

// Fill everything except the signature and discriminator fields with 'PAGE' — as if the writer didn't fill it.
std::vector<std::uint8_t> makePageFilledKernelHeader() {
    std::vector<std::uint8_t> buffer(0x2000, 0U);
    static const char kFill[4] = {'P', 'A', 'G', 'E'};
    for (std::size_t index = 0; index < buffer.size(); ++index) {
        buffer[index] = static_cast<std::uint8_t>(kFill[index % 4U]);
    }
    putAscii(buffer, 0x00, "PAGE");
    putAscii(buffer, 0x04, "DU64");
    putU32(buffer, 0x30, 0x8664U);
    putU32(buffer, 0xF98, 4U);
    return buffer;
}

// Header with all zeros except signature, architecture, and type. Used to distinguish '0 is a true value' from '0 is unset'.
std::vector<std::uint8_t> makeZeroedKernelHeader() {
    std::vector<std::uint8_t> buffer(0x2000, 0U);
    putAscii(buffer, 0x00, "PAGE");
    putAscii(buffer, 0x04, "DU64");
    putU32(buffer, 0x30, 0x8664U);
    putU32(buffer, 0xF98, 4U);
    return buffer;
}

std::vector<std::uint8_t> makeUserMinidump(std::size_t size) {
    std::vector<std::uint8_t> buffer(size, 0U);
    if (size >= 4U) {
        putAscii(buffer, 0x00, "MDMP");
    }
    if (size >= 8U) {
        putU32(buffer, 0x04, 0x0000A793U);  // MINIDUMP_VERSION
    }
    if (size >= 0x20U) {
        putU32(buffer, 0x08, 7U);        // NumberOfStreams
        putU32(buffer, 0x0C, 0x00000020U);  // StreamDirectoryRva
    }
    return buffer;
}

std::vector<std::uint8_t> makeKernel32Header() {
    std::vector<std::uint8_t> buffer(0x1000, 0U);
    putAscii(buffer, 0x00, "PAGE");
    putAscii(buffer, 0x04, "DUMP");
    return buffer;
}

// Deterministic pseudo-random bytes. Fixed seed ensures identical results across runs.
std::vector<std::uint8_t> makeRandomBytes(std::size_t size, std::uint64_t seed) {
    std::vector<std::uint8_t> buffer(size, 0U);
    std::uint64_t state = seed;
    for (std::size_t index = 0; index < size; ++index) {
        state = state * 6364136223846793005ULL + 1442695040888963407ULL;
        buffer[index] = static_cast<std::uint8_t>((state >> 33U) & 0xFFU);
    }
    return buffer;
}

// ---------------------------------------------------------------------------
// C-02 File identification and support scope
// ---------------------------------------------------------------------------
void testRecognition(Reporter& s) {
    // Valid small kernel dump (DumpType=4).
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kKernelSmall,
                 L"C-02 small kernel dump is recognized as KernelSmall");
        s.expect(kRecognition.family == SignatureFamily::kKernelPage64,
                 L"C-02 small kernel dump reports the PAGEDU64 signature family");
        s.expect(kRecognition.reason == RecognitionReason::kRecognized,
                 L"C-02 small kernel dump recognition reason is Recognized");
        s.expect(kRecognition.architecture == TargetArchitecture::kX64,
                 L"C-02 small kernel dump target architecture is x64");
        s.expect(kRecognition.rawDumpType == OptionalU64::of(4U),
                 L"C-02 raw DumpType 4 survives classification");
        s.expect(kRecognition.rawMachineType == OptionalU64::of(0x8664U),
                 L"C-02 raw machine type 0x8664 survives classification");
        s.expect(kRecognition.rawSignature == OptionalU64::of(0x45474150U),
                 L"C-02 raw PAGE signature is kept losslessly");
        s.expect(kRecognition.rawValidDump == OptionalU64::of(0x34365544U),
                 L"C-02 raw DU64 discriminator is kept losslessly");
        s.expect(kRecognition.parseAttempted,
                 L"C-02 a recognized kernel dump reports that fields were actually read");
        s.expect(kRecognition.outcome.status == CollectionStatus::kSuccess,
                 L"C-02 recognized dump carries a Success collection outcome");
        s.expect(kRecognition.fileSize == OptionalU64::of(0x2000ULL),
                 L"C-02 recognition falls back to the provided window size as file size");
        s.expect(!recognitionIsDamagedRatherThanUnsupported(kRecognition),
                 L"C-02 a healthy dump is not reported as damaged");
        s.expect(dumpKindCarriesKernelFacts(kRecognition.kind),
                 L"C-02 KernelSmall is allowed to carry kernel bugcheck facts");
    }

    // DumpType=3 (header-only dumps) also belongs to KernelSmall, but the original value is preserved.
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(3U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kKernelSmall,
                 L"C-02 header-only dump is treated with the small-dump content upper bound");
        s.expect(kRecognition.rawDumpType == OptionalU64::of(3U),
                 L"C-02 header-only dump keeps raw DumpType 3 so the report can tell them apart");
    }

    // Valid kernel memory dump (DumpType=2).
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(2U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kKernelMemory,
                 L"C-02 kernel memory dump is recognized as KernelMemory");
        s.expect(kRecognition.reason == RecognitionReason::kRecognized,
                 L"C-02 kernel memory dump recognition reason is Recognized");
    }
    for (const std::uint32_t kDumpType : {1U, 5U, 6U, 7U}) {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(kDumpType, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kKernelMemory,
                 L"C-02 every memory-bearing DumpType maps to KernelMemory");
    }

    // User-mode minidump — Red line: must never be treated as a kernel dump.
    {
        const std::vector<std::uint8_t> kBytes = makeUserMinidump(0x400);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kUserMinidump,
                 L"C-02 a user-mode MDMP is recognized as UserMinidump");
        s.expect(kRecognition.family == SignatureFamily::kMdmp,
                 L"C-02 a user-mode MDMP reports the MDMP signature family");
        s.expect(kRecognition.kind != DumpKind::kKernelSmall &&
                     kRecognition.kind != DumpKind::kKernelMemory,
                 L"C-02 red line: a user-mode minidump is never classified as a kernel dump");
        s.expect(!dumpKindCarriesKernelFacts(kRecognition.kind),
                 L"C-02 a user minidump is not allowed to carry kernel bugcheck facts");
        s.expect(kRecognition.architecture == TargetArchitecture::kUnknown,
                 L"C-02 MDMP architecture stays Unknown because the header does not carry it");
        s.expect(kRecognition.rawMachineType == OptionalU64::unset(),
                 L"C-02 MDMP raw machine type stays unset rather than defaulting to zero");
    }

    // Empty file.
    {
        const std::vector<std::uint8_t> kBytes;
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kNotADump,
                 L"C-02 an empty file is NotADump");
        s.expect(kRecognition.reason == RecognitionReason::kEmptyFile,
                 L"C-02 an empty file reports the EmptyFile reason, not a generic failure");
        s.expect(kRecognition.family == SignatureFamily::kNone,
                 L"C-02 an empty file has no signature family");
        s.expect(!kRecognition.parseAttempted,
                 L"C-02 an empty file never claims fields were parsed");
        s.expect(kRecognition.outcome.status == CollectionStatus::kError,
                 L"C-02 an empty file yields an error outcome, not Success");
        s.expect(kRecognition.outcome.nativeCode ==
                     OptionalU64::of(static_cast<std::uint64_t>(RecognitionReason::kEmptyFile)),
                 L"C-02 the recognition outcome preserves the raw reason code");
        s.expect(kRecognition.outcome.nativeCodeDomain == "KSWORD_DUMPRECOGNITION",
                 L"C-02 the recognition outcome names its own error domain");
        s.expect(recognitionIsDamagedRatherThanUnsupported(kRecognition),
                 L"C-02 an empty file is a file problem, not an unsupported format");
    }

    // 7 bytes: signature cannot be read at all.
    {
        const std::vector<std::uint8_t> kBytes(7U, 0x41U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.reason == RecognitionReason::kTooSmallForSignature,
                 L"C-02 a 7-byte file reports TooSmallForSignature");
        s.expect(kRecognition.kind == DumpKind::kNotADump,
                 L"C-02 a 7-byte file is NotADump");
        s.expect(kRecognition.rawSignature == OptionalU64::unset(),
                 L"C-02 an unreadable signature stays unset rather than defaulting to zero");
    }

    // Truncated kernel dump file (0x100 bytes).
    {
        std::vector<std::uint8_t> full = makeKernelHeader(4U, 0x8664U);
        const std::vector<std::uint8_t> kBytes(full.begin(), full.begin() + 0x100);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kUnsupported,
                 L"C-02 a truncated kernel dump cannot converge to Small or Memory");
        s.expect(kRecognition.family == SignatureFamily::kKernelPage64,
                 L"C-02 a truncated kernel dump still reports its signature family");
        s.expect(kRecognition.reason == RecognitionReason::kTruncatedHeader,
                 L"C-02 a truncated kernel dump reports TruncatedHeader");
        s.expect(kRecognition.architecture == TargetArchitecture::kX64,
                 L"C-02 a truncated kernel dump still reads the machine type at 0x30");
        s.expect(kRecognition.rawDumpType == OptionalU64::unset(),
                 L"C-02 a truncated kernel dump leaves DumpType unset instead of guessing");
        s.expect(kRecognition.outcome.status == CollectionStatus::kPartial,
                 L"C-02 a truncated header is a partial collection, not an unsupported format");
        s.expect(recognitionIsDamagedRatherThanUnsupported(kRecognition),
                 L"C-02 truncation is reported as damage, not as unsupported");
        s.expect(kRecognition.headerBytesRequired == OptionalU64::of(0x2000ULL),
                 L"C-02 the required header size is stated so the UI can explain the shortfall");
    }

    // Truncated user-mode minidump: The family remains trusted — still proving it is 'not a kernel dump'.
    {
        const std::vector<std::uint8_t> kBytes = makeUserMinidump(16U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.family == SignatureFamily::kMdmp,
                 L"C-02 a truncated MDMP still proves it is a user-mode minidump family");
        s.expect(kRecognition.kind == DumpKind::kUnsupported,
                 L"C-02 a truncated MDMP does not claim a parsable kind");
        s.expect(kRecognition.reason == RecognitionReason::kTruncatedHeader,
                 L"C-02 a truncated MDMP reports TruncatedHeader");
        s.expect(kRecognition.kind != DumpKind::kKernelSmall &&
                     kRecognition.kind != DumpKind::kKernelMemory,
                 L"C-02 red line: a truncated user minidump is still never a kernel dump");
    }

    // The caller provided only the first 0x1000 bytes, but the file declares 0x2000 bytes.
    {
        const std::vector<std::uint8_t> kFull = makeKernelHeader(4U, 0x8664U);
        const std::vector<std::uint8_t> kHead(kFull.begin(), kFull.begin() + 0x1000);
        const DumpRecognition kRecognition = recognizeDump(view(kHead), OptionalU64::of(0x2000ULL));
        s.expect(kRecognition.reason == RecognitionReason::kTruncatedHeader,
                 L"C-02 a short read window is reported instead of silently parsing garbage");
        s.expect(kRecognition.bytesProvided == OptionalU64::of(0x1000ULL),
                 L"C-02 the provided window size is recorded");
        s.expect(kRecognition.fileSize == OptionalU64::of(0x2000ULL),
                 L"C-02 the declared file size is recorded separately from the window");
    }

    // The window lands exactly in the middle of a read offset. This is the sole trigger condition for
    // readLittleEndianU32/U64 length boundary violations: offset < size < offset + 4 (or +8). The truncation
    // samples above are all 'chunks cut off entirely'; the window end never falls within a field, so that boundary
    // was always zero-covered. Removing the `bytes.size() - offset < 4U` check leaves all assertions passing, yet
    // the same code immediately triggers an access violation (ACCESS_VIOLATION) when probed against guard pages.
    //
    // Expected values are hardcoded: MachineImageType at 0x30, DumpType at 0xF98, SystemUpTime at 0x1030,
    // and WriterStatus at 0x1048 in DUMP_HEADER64 (all offsets defined in this file, unrelated to
    // production code). The window length is derived from internal cut points within each of these fields.
    {
        const std::vector<std::uint8_t> kFull = makeKernelHeader(4U, 0x8664U);
        const std::size_t kPartialWindows[] = {
            0x30U, 0x31U, 0x32U, 0x33U,          // Internal MachineImageType
            0x10U, 0x11U, 0x12U, 0x13U,          // DirectoryTableBase lower half
            0x14U, 0x15U, 0x16U, 0x17U,          // DirectoryTableBase upper half
            0xF98U, 0xF99U, 0xF9AU, 0xF9BU,      // DumpType internal
            0x1030U, 0x1031U, 0x1034U, 0x1037U,  // SystemUpTime internal
            0x1048U, 0x1049U, 0x104AU, 0x104BU,  // WriterStatus internal.
        };
        bool allSafe = true;
        bool allUnparsedMachine = true;
        bool allUnparsedDumpType = true;
        bool allFieldsAccountedFor = true;
        for (const std::size_t kWindowSize : kPartialWindows) {
            const std::vector<std::uint8_t> kWindow(kFull.begin(),
                                                   kFull.begin() +
                                                       static_cast<std::ptrdiff_t>(kWindowSize));
            const DumpRecognition kRecognition =
                recognizeDump(view(kWindow), OptionalU64::of(0x2000ULL));
            // Note: An incomplete header will never converge to a parsable kind and will never report 'recognition success'.
            allSafe = allSafe && kRecognition.kind == DumpKind::kUnsupported &&
                      kRecognition.reason == RecognitionReason::kTruncatedHeader;
            if (kWindowSize <= 0x33U) {
                // The machine type field was not fully read: must unset; do not construct a value from a partial field.
                allUnparsedMachine = allUnparsedMachine && !kRecognition.rawMachineType.present;
            }
            allUnparsedDumpType = allUnparsedDumpType && !kRecognition.rawDumpType.present;

            const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kWindow));
            allFieldsAccountedFor =
                allFieldsAccountedFor && kFacts.presentFieldCount() == 0U &&
                kFacts.notParsedFieldCount() == 12U && kFacts.fieldCount() == 12U &&
                !kFacts.hasAnyFact();
        }
        s.expect(allSafe,
                 L"C-02 a window that stops inside a header field never converges to a parsable kind");
        s.expect(allUnparsedMachine,
                 L"C-02 a machine type whose last bytes are missing stays unset instead of half-read");
        s.expect(allUnparsedDumpType,
                 L"C-02 a DumpType whose last bytes are missing stays unset instead of half-read");
        s.expect(allFieldsAccountedFor,
                 L"C-03 every field of a mid-field truncated window is NotParsed, none fabricated");

        // Negative case: The last byte of the machine type is only allowed to appear when the window reads exactly up to that byte.
        const std::vector<std::uint8_t> kExact(kFull.begin(), kFull.begin() + 0x34);
        const DumpRecognition kRecognition = recognizeDump(view(kExact), OptionalU64::of(0x2000ULL));
        s.expect(kRecognition.rawMachineType == OptionalU64::of(0x8664U),
                 L"C-02 one byte more and the machine type reads exactly, proving the bound is off-by-none");
        s.expect(kRecognition.reason == RecognitionReason::kTruncatedHeader,
                 L"C-02 reading the machine type does not make a truncated header complete");
    }

    // Scan the entire header length byte-by-byte: no crashes in any window, no false claims of successful parsing, and field accounting must always equal 12.
    {
        const std::vector<std::uint8_t> kFull = makeKernelHeader(4U, 0x8664U);
        bool neverClaimsSuccess = true;
        bool accountsAlwaysBalance = true;
        for (std::size_t windowSize = 0; windowSize < 0x120U; ++windowSize) {
            const std::vector<std::uint8_t> kWindow(kFull.begin(),
                                                   kFull.begin() +
                                                       static_cast<std::ptrdiff_t>(windowSize));
            const DumpRecognition kRecognition =
                recognizeDump(view(kWindow), OptionalU64::of(0x2000ULL));
            neverClaimsSuccess = neverClaimsSuccess && !dumpKindCarriesKernelFacts(kRecognition.kind);
            const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kWindow));
            accountsAlwaysBalance =
                accountsAlwaysBalance &&
                (kFacts.presentFieldCount() + kFacts.notRecordedFieldCount() +
                 kFacts.notParsedFieldCount()) == 12U;
        }
        s.expect(neverClaimsSuccess,
                 L"C-02 no truncated window length ever yields a kind that carries kernel facts");
        s.expect(accountsAlwaysBalance,
                 L"C-03 the field account adds up to twelve at every truncated window length");
    }

    // Random bytes.
    {
        const std::vector<std::uint8_t> kBytes = makeRandomBytes(4096U, 0x1234ABCDULL);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kNotADump,
                 L"C-02 random bytes are NotADump");
        s.expect(kRecognition.reason == RecognitionReason::kUnknownSignature,
                 L"C-02 random bytes report UnknownSignature");
        s.expect(!kRecognition.parseAttempted,
                 L"C-02 random bytes never claim a format parse happened");
        s.expect(!recognitionIsDamagedRatherThanUnsupported(kRecognition),
                 L"C-02 an unknown signature is not reported as a damaged dump");
    }

    // 32-bit kernel dump: Explicitly reject; do not pretend parsing succeeded.
    {
        const std::vector<std::uint8_t> kBytes = makeKernel32Header();
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kUnsupported,
                 L"C-02 a 32-bit PAGEDUMP is explicitly unsupported");
        s.expect(kRecognition.family == SignatureFamily::kKernelPage32,
                 L"C-02 a 32-bit PAGEDUMP reports its own signature family");
        s.expect(kRecognition.reason == RecognitionReason::kUnsupportedKernelBitness,
                 L"C-02 a 32-bit PAGEDUMP names bitness as the reason");
        s.expect(kRecognition.outcome.status == CollectionStatus::kUnsupported,
                 L"C-02 an unsupported format yields the Unsupported status");
        s.expect(!kRecognition.parseAttempted,
                 L"C-02 an unsupported 32-bit dump is not parsed with the 64-bit layout");
        s.expect(!recognitionIsDamagedRatherThanUnsupported(kRecognition),
                 L"C-02 unsupported bitness is a format limit, not file damage");
    }

    // 'PAGE' but the discriminator field is unrecognized.
    {
        std::vector<std::uint8_t> bytes = makeKernelHeader(4U, 0x8664U);
        putAscii(bytes, 0x04, "XXXX");
        const DumpRecognition kRecognition = recognizeDump(view(bytes), OptionalU64::unset());
        s.expect(kRecognition.reason == RecognitionReason::kUnknownSignature,
                 L"C-02 a PAGE signature with an unknown discriminator is not force-parsed");
        s.expect(kRecognition.kind == DumpKind::kNotADump,
                 L"C-02 an unknown PAGE discriminator yields NotADump");
    }

    // Non-x64 architecture.
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0xAA64U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kUnsupported,
                 L"C-02 an ARM64 kernel dump is unsupported this round");
        s.expect(kRecognition.reason == RecognitionReason::kUnsupportedArchitecture,
                 L"C-02 an ARM64 kernel dump names architecture as the reason");
        s.expect(kRecognition.architecture == TargetArchitecture::kArm64,
                 L"C-02 the ARM64 architecture is still reported, not hidden");
    }
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x014CU);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.architecture == TargetArchitecture::kX86,
                 L"C-02 an x86 machine type is classified as X86");
    }
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x01C4U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.architecture == TargetArchitecture::kArm,
                 L"C-02 an ARM machine type is classified as Arm");
    }
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x5555U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.architecture == TargetArchitecture::kOther,
                 L"C-02 an unrecognized machine type is Other, with the raw value preserved");
        s.expect(kRecognition.rawMachineType == OptionalU64::of(0x5555U),
                 L"C-02 the raw machine type is preserved for an unknown architecture");
    }
    {
        // The 'PAGE' padding falls on the machine type field: this indicates 'not filled' rather than a valid value.
        std::vector<std::uint8_t> bytes = makeKernelHeader(4U, 0x8664U);
        putU32(bytes, 0x30, 0x45474150U);
        const DumpRecognition kRecognition = recognizeDump(view(bytes), OptionalU64::unset());
        s.expect(kRecognition.architecture == TargetArchitecture::kUnknown,
                 L"C-02 a PAGE-filled machine type is Unknown, never a fabricated architecture");
        s.expect(kRecognition.reason == RecognitionReason::kUnsupportedArchitecture,
                 L"C-02 an unknown architecture is rejected rather than assumed to be x64");
    }

    // Unknown DumpType.
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(99U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kUnsupported,
                 L"C-02 an unknown DumpType is not force-mapped to a supported kind");
        s.expect(kRecognition.reason == RecognitionReason::kUnsupportedDumpType,
                 L"C-02 an unknown DumpType names DumpType as the reason");
        s.expect(kRecognition.rawDumpType == OptionalU64::of(99U),
                 L"C-02 the raw unknown DumpType is preserved");
    }

    // Parsing does not rely on extension: the same MDMP bytes are always a user-mode dump regardless of caller intent.
    // The API has no path/extension parameters; this assertion verifies the consequence guaranteed by the interface shape.
    {
        const std::vector<std::uint8_t> kMdmp = makeUserMinidump(0x200);
        const DumpRecognition kFirst = recognizeDump(view(kMdmp), OptionalU64::of(0x200ULL));
        const DumpRecognition kSecond = recognizeDump(view(kMdmp), OptionalU64::of(0x200ULL));
        s.expect(kFirst.kind == kSecond.kind && kFirst.kind == DumpKind::kUserMinidump,
                 L"C-02 classification depends only on bytes, never on a name or extension");
    }

    // Name coverage: Each enumerator has a unique name to prevent the UI from displaying two distinct states as the same string.
    s.expect(std::string(dumpKindName(DumpKind::kNotADump)) == "NotADump" &&
                 std::string(dumpKindName(DumpKind::kUnsupported)) == "Unsupported" &&
                 std::string(dumpKindName(DumpKind::kUserMinidump)) == "UserMinidump" &&
                 std::string(dumpKindName(DumpKind::kKernelSmall)) == "KernelSmall" &&
                 std::string(dumpKindName(DumpKind::kKernelMemory)) == "KernelMemory",
             L"C-02 every DumpKind has its own distinct name");
    s.expect(std::string(signatureFamilyName(SignatureFamily::kNone)) == "None" &&
                 std::string(signatureFamilyName(SignatureFamily::kMdmp)) == "Mdmp" &&
                 std::string(signatureFamilyName(SignatureFamily::kKernelPage64)) == "KernelPage64" &&
                 std::string(signatureFamilyName(SignatureFamily::kKernelPage32)) == "KernelPage32",
             L"C-02 every SignatureFamily has its own distinct name");
    s.expect(std::string(targetArchitectureName(TargetArchitecture::kOther)) == "Other" &&
                 std::string(targetArchitectureName(TargetArchitecture::kUnknown)) == "Unknown",
             L"C-02 TargetArchitecture names cover Unknown and Other separately");
    s.expect(std::string(recognitionReasonName(RecognitionReason::kRecognized)) == "Recognized",
             L"C-02 RecognitionReason exposes a stable name for reports");

    // Default construction: must not be 'recognition successful'.
    {
        const DumpRecognition kFresh;
        s.expect(kFresh.kind == DumpKind::kNotADump && !kFresh.parseAttempted &&
                     kFresh.outcome.status == CollectionStatus::kNotCollected,
                 L"C-02 a default-constructed recognition is NotADump and NotCollected");
    }
}

// ---------------------------------------------------------------------------
// C-03 Crash facts
// ---------------------------------------------------------------------------
void testBugCheckFacts(Reporter& s) {
    // Normal small dump with all fields having truthy values.
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));

        s.expect(kFacts.dumpKind == DumpKind::kKernelSmall,
                 L"C-03 the facts record which dump kind they came from");
        s.expect(kFacts.code == DumpField::present(kFixtureBugCheckCode),
                 L"C-03 bugcheck code 0x7E is read back exactly");
        s.expect(kFacts.parameters[0] == DumpField::present(kFixtureParam0),
                 L"C-03 bugcheck parameter 0 is read back exactly");
        s.expect(kFacts.parameters[1] == DumpField::present(kFixtureParam1),
                 L"C-03 bugcheck parameter 1 is read back exactly");
        s.expect(kFacts.parameters[2].availability == DumpFieldAvailability::kPresent &&
                     kFacts.parameters[2].value == OptionalU64::of(0ULL),
                 L"C-03 a genuine zero parameter is Present(0), not reported as missing");
        s.expect(kFacts.parameters[3] == DumpField::present(kFixtureParam3),
                 L"C-03 bugcheck parameter 3 is read back exactly");
        s.expect(kFacts.targetOsMajor == DumpField::present(kFixtureMajorVersion),
                 L"C-03 the target OS major version is read back exactly");
        s.expect(kFacts.targetOsBuild == DumpField::present(kFixtureBuildNumber),
                 L"C-03 the target OS build number is read back exactly");
        s.expect(kFacts.processorCount == DumpField::present(kFixtureProcessorCount),
                 L"C-03 the processor count is read back exactly");
        s.expect(kFacts.crashTimeUtc100ns == DumpField::present(kFixtureCrashTime),
                 L"C-03 the crash FILETIME is read back exactly and losslessly");
        s.expect(kFacts.uptime100ns == DumpField::present(kFixtureUptime),
                 L"C-03 the uptime is read back exactly and losslessly");
        s.expect(kFacts.writerStatus.availability == DumpFieldAvailability::kPresent &&
                     kFacts.writerStatus.value == OptionalU64::of(0ULL),
                 L"C-03 writer status zero means healthy and stays Present(0)");
        s.expect(kFacts.directoryTableBase == DumpField::present(kFixtureDirectoryTableBase),
                 L"C-03 the crash-time CR3 is read back exactly");
        s.expect(kFacts.presentFieldCount() == 12U && kFacts.fieldCount() == 12U,
                 L"C-03 a complete header yields twelve present fields");
        s.expect(kFacts.notRecordedFieldCount() == 0U && kFacts.notParsedFieldCount() == 0U,
                 L"C-03 a complete header reports no missing and no unparsed fields");
        s.expect(kFacts.hasAnyFact(), L"C-03 a complete header has facts");
        s.expect(kFacts.outcome.status == CollectionStatus::kSuccess,
                 L"C-03 a fully readable header yields a Success outcome");
        s.expect(!kFacts.windowShorterThanFile,
                 L"C-03 a full window is not flagged as shorter than the file");
        s.expect(kFacts.code.consistent() && kFacts.parameters[2].consistent() &&
                     kFacts.uptime100ns.consistent(),
                 L"C-03 Present fields carry a value and only Present fields do");
    }

    // 'PAGE' filled: every cell was read, but every cell says 'not written'.
    {
        const std::vector<std::uint8_t> kBytes = makePageFilledKernelHeader();
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        s.expect(kRecognition.kind == DumpKind::kKernelSmall,
                 L"C-03 a PAGE-filled but well-formed header is still recognized");
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));
        s.expect(kFacts.notRecordedFieldCount() == 12U,
                 L"C-03 every PAGE-filled field is reported as NotRecorded");
        s.expect(kFacts.presentFieldCount() == 0U,
                 L"C-03 red line: PAGE fill never becomes a present value");
        s.expect(kFacts.notParsedFieldCount() == 0U,
                 L"C-03 PAGE fill is NotRecorded, which is different from NotParsed");
        s.expect(!kFacts.hasAnyFact(),
                 L"C-03 a PAGE-filled header yields no facts at all");
        s.expect(kFacts.code.value == OptionalU64::unset() &&
                     kFacts.uptime100ns.value == OptionalU64::unset() &&
                     kFacts.parameters[0].value == OptionalU64::unset(),
                 L"C-03 red line: a missing field never carries a fabricated zero");
        s.expect(kFacts.outcome.status == CollectionStatus::kSuccess,
                 L"C-03 reading every field successfully is Success even when nothing was recorded");
        s.expect(!kFacts.hasAnyFact() && kFacts.outcome.status == CollectionStatus::kSuccess,
                 L"C-03 Success does not imply facts exist, and the UI must check hasAnyFact");
    }

    // All-0 header: must distinguish which fields contain actual 0 values versus which fields are 'unfilled'.
    {
        const std::vector<std::uint8_t> kBytes = makeZeroedKernelHeader();
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));
        s.expect(kFacts.code.availability == DumpFieldAvailability::kNotRecorded,
                 L"C-03 bugcheck code zero is not a valid stop code, so it is NotRecorded");
        s.expect(kFacts.parameters[0].availability == DumpFieldAvailability::kPresent &&
                     kFacts.parameters[1].availability == DumpFieldAvailability::kPresent &&
                     kFacts.parameters[2].availability == DumpFieldAvailability::kPresent &&
                     kFacts.parameters[3].availability == DumpFieldAvailability::kPresent,
                 L"C-03 all four zero parameters stay Present because zero is legal there");
        s.expect(kFacts.writerStatus.availability == DumpFieldAvailability::kPresent,
                 L"C-03 writer status zero stays Present because zero means healthy");
        s.expect(kFacts.crashTimeUtc100ns.availability == DumpFieldAvailability::kNotRecorded &&
                     kFacts.uptime100ns.availability == DumpFieldAvailability::kNotRecorded,
                 L"C-03 a zero crash time or uptime is treated as not recorded, never as a real time");
        s.expect(kFacts.targetOsBuild.availability == DumpFieldAvailability::kNotRecorded &&
                     kFacts.targetOsMajor.availability == DumpFieldAvailability::kNotRecorded &&
                     kFacts.processorCount.availability == DumpFieldAvailability::kNotRecorded &&
                     kFacts.directoryTableBase.availability == DumpFieldAvailability::kNotRecorded,
                 L"C-03 zeroed build, processor count and CR3 are reported as not recorded");
        s.expect(kFacts.presentFieldCount() == 5U && kFacts.notRecordedFieldCount() == 7U,
                 L"C-03 the zeroed header yields exactly five present and seven missing fields");
    }

    // Collection window shorter than file: field-level NotParsed, distinct from NotRecorded.
    {
        const std::vector<std::uint8_t> kBytes = makeKernelHeader(4U, 0x8664U);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const std::span<const std::uint8_t> kShortWindow = view(kBytes).subspan(0, 0x1000);
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, kShortWindow);
        s.expect(kFacts.uptime100ns.availability == DumpFieldAvailability::kNotParsed &&
                     kFacts.writerStatus.availability == DumpFieldAvailability::kNotParsed,
                 L"C-03 fields past the read window are NotParsed, not NotRecorded");
        s.expect(kFacts.code == DumpField::present(kFixtureBugCheckCode),
                 L"C-03 fields inside the read window are still read exactly");
        s.expect(kFacts.crashTimeUtc100ns == DumpField::present(kFixtureCrashTime),
                 L"C-03 the crash time at 0xFA8 is inside a 0x1000 window and is read");
        s.expect(kFacts.presentFieldCount() == 10U && kFacts.notParsedFieldCount() == 2U,
                 L"C-03 a short window yields exactly ten present and two unparsed fields");
        s.expect(kFacts.outcome.status == CollectionStatus::kPartial,
                 L"C-03 a partially readable header yields a Partial outcome");
        s.expect(kFacts.windowShorterThanFile,
                 L"C-03 the report can tell a short window apart from a short file");
        s.expect(kFacts.bytesProvided == OptionalU64::of(0x1000ULL) &&
                     kFacts.fileSizeDeclared == OptionalU64::of(0x2000ULL),
                 L"C-03 both the window size and the declared file size are kept");
    }

    // User-mode minidump: this format lacks a bugcheck field -> NotRecorded (known to be absent).
    {
        const std::vector<std::uint8_t> kBytes = makeUserMinidump(0x400);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));
        s.expect(kFacts.notRecordedFieldCount() == 12U && kFacts.presentFieldCount() == 0U,
                 L"C-03 a user minidump reports all bugcheck fields as NotRecorded");
        s.expect(kFacts.outcome.status == CollectionStatus::kUnsupported,
                 L"C-03 asking a user minidump for bugcheck facts is Unsupported, not Success");
        s.expect(kFacts.outcome.message == "dump.facts.user_minidump_has_no_bugcheck",
                 L"C-03 the unsupported reason is stated with a stable key");
    }

    // Random file: Parsing not run -> NotParsed (unknown if present), distinct from the previous case.
    {
        const std::vector<std::uint8_t> kBytes = makeRandomBytes(4096U, 0x99ULL);
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));
        s.expect(kFacts.notParsedFieldCount() == 12U,
                 L"C-03 a non-dump reports all fields as NotParsed, never as NotRecorded");
        s.expect(kFacts.outcome.status == CollectionStatus::kNotCollected,
                 L"C-03 a non-dump yields NotCollected rather than a failure of collection");
        s.expect(!statusCarriesObservation(kFacts.outcome.status),
                 L"C-03 a NotCollected facts outcome carries no observation");
    }

    // Unsupported 32-bit dump: also results in NotParsed, but the outcome is Unsupported.
    {
        const std::vector<std::uint8_t> kBytes = makeKernel32Header();
        const DumpRecognition kRecognition = recognizeDump(view(kBytes), OptionalU64::unset());
        const BugCheckFacts kFacts = extractBugCheckFacts(kRecognition, view(kBytes));
        s.expect(kFacts.notParsedFieldCount() == 12U,
                 L"C-03 an unsupported format reports all fields as NotParsed");
        s.expect(kFacts.outcome.status == CollectionStatus::kUnsupported,
                 L"C-03 an unsupported format yields Unsupported, distinct from NotCollected");
    }

    // Tri-state and default construction.
    {
        const DumpField kFresh;
        s.expect(kFresh.availability == DumpFieldAvailability::kNotParsed && !kFresh.value.present,
                 L"C-03 a default-constructed field is NotParsed with no value");
        s.expect(DumpField::notRecorded().availability == DumpFieldAvailability::kNotRecorded &&
                     !DumpField::notRecorded().value.present,
                 L"C-03 a NotRecorded field carries no value");
        s.expect(DumpField::present(0ULL).value == OptionalU64::of(0ULL),
                 L"C-03 Present(0) is a real zero and stays distinguishable from missing");
        s.expect(DumpField::present(0ULL) != DumpField::notRecorded(),
                 L"C-03 Present(0) never compares equal to NotRecorded");
        s.expect(DumpField::notRecorded() != DumpField::notParsed(),
                 L"C-03 NotRecorded never compares equal to NotParsed");
        s.expect(std::string(dumpFieldAvailabilityName(DumpFieldAvailability::kNotParsed)) == "NotParsed" &&
                     std::string(dumpFieldAvailabilityName(DumpFieldAvailability::kNotRecorded)) ==
                         "NotRecorded" &&
                     std::string(dumpFieldAvailabilityName(DumpFieldAvailability::kPresent)) == "Present",
                 L"C-03 all three availability states have distinct names");
        const BugCheckFacts kFreshFacts;
        s.expect(!kFreshFacts.hasAnyFact() && kFreshFacts.notParsedFieldCount() == 12U,
                 L"C-03 default-constructed facts contain nothing and claim nothing");
    }
}

// ---------------------------------------------------------------------------
// C-04 Symbol exact match
// ---------------------------------------------------------------------------
PdbIdentity makePdb(std::uint8_t seed, std::uint32_t age) {
    PdbIdentity identity;
    for (std::size_t index = 0; index < identity.guid.size(); ++index) {
        identity.guid[index] = static_cast<std::uint8_t>(seed + index);
    }
    identity.age = age;
    identity.present = true;
    identity.pdbName = "ntkrnlmp.pdb";
    return identity;
}

void testSymbolMatching(Reporter& s) {
    const PdbIdentity kWanted = makePdb(0x10U, 1U);
    const PdbIdentity kSameBuild = makePdb(0x10U, 1U);
    const PdbIdentity kOlderAge = makePdb(0x10U, 2U);
    const PdbIdentity kOtherGuid = makePdb(0x20U, 1U);
    const PdbIdentity kAbsent;  // Default construction: no identity

    s.expect(samePdbIdentity(kWanted, kSameBuild),
             L"C-04 identical GUID and age compare as the same PDB identity");
    s.expect(!samePdbIdentity(kWanted, kOlderAge),
             L"C-04 the same GUID with a different age is not the same PDB");
    s.expect(!samePdbIdentity(kWanted, kOtherGuid),
             L"C-04 a different GUID is not the same PDB");
    s.expect(!samePdbIdentity(kAbsent, kAbsent),
             L"C-04 two empty identities never compare as matching");
    s.expect(!samePdbIdentity(kWanted, kAbsent),
             L"C-04 a missing identity on either side blocks a match");

    // Four SymbolMatch branches.
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kNotAttempted, kAbsent, kAbsent) ==
                 SymbolMatch::kNotAttempted,
             L"C-04 a default attempt with empty identities is NotAttempted, never Matched");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kFileNotFound, kWanted, kAbsent) ==
                 SymbolMatch::kAbsent,
             L"C-04 a missing PDB file yields Absent");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kLoadFailed, kWanted, kAbsent) ==
                 SymbolMatch::kAbsent,
             L"C-04 a PDB that fails to load yields Absent, with the reason kept in attempt");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kFileLoaded, kWanted, kOlderAge) ==
                 SymbolMatch::kWrongVersion,
             L"C-04 a loaded PDB with a mismatched age is WrongVersion");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kFileLoaded, kWanted, kOtherGuid) ==
                 SymbolMatch::kWrongVersion,
             L"C-04 a loaded PDB with a mismatched GUID is WrongVersion");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kFileLoaded, kAbsent, kSameBuild) ==
                 SymbolMatch::kWrongVersion,
             L"C-04 a loaded PDB that cannot be proven to match is never Matched");
    s.expect(deriveSymbolMatch(SymbolLoadAttempt::kFileLoaded, kWanted, kSameBuild) ==
                 SymbolMatch::kMatched,
             L"C-04 a loaded PDB with matching GUID and age is Matched");

    // Red line for mismatched PDBs: no function names or line numbers, only 'module+offset' is available.
    ModuleSymbolState wrongVersionState;
    wrongVersionState.moduleName = "acme_filter.sys";
    wrongVersionState.wanted = kWanted;
    wrongVersionState.loaded = kOlderAge;
    wrongVersionState.attempt = SymbolLoadAttempt::kFileLoaded;
    wrongVersionState.match =
        deriveSymbolMatch(wrongVersionState.attempt, wrongVersionState.wanted,
                          wrongVersionState.loaded);
    wrongVersionState.cacheSource = SymbolCacheSource::kLocalCache;
    s.expect(wrongVersionState.match == SymbolMatch::kWrongVersion,
             L"C-04 the wrong-version fixture really is WrongVersion");
    s.expect(!mayReportFunctionName(wrongVersionState),
             L"C-04 red line: a wrong-version PDB may not produce a definite function name");
    s.expect(!mayReportSourceLine(wrongVersionState),
             L"C-04 red line: a wrong-version PDB may not produce a source line");
    s.expect(allowedAttribution(wrongVersionState, true) == SymbolAttribution::kModulePlusOffset,
             L"C-04 a wrong-version PDB with a known base allows only module plus offset");
    s.expect(allowedAttribution(wrongVersionState, false) == SymbolAttribution::kModuleOnly,
             L"C-04 a wrong-version PDB without a base allows only the module name");

    ModuleSymbolState absentState;
    absentState.moduleName = "acme_filter.sys";
    absentState.attempt = SymbolLoadAttempt::kFileNotFound;
    absentState.match = SymbolMatch::kAbsent;
    absentState.cacheSource = SymbolCacheSource::kNotLoaded;
    s.expect(!mayReportFunctionName(absentState) && !mayReportSourceLine(absentState),
             L"C-04 a module without symbols may not produce a function name or line");
    s.expect(allowedAttribution(absentState, true) == SymbolAttribution::kModulePlusOffset,
             L"C-04 a module without symbols still shows module plus offset");

    ModuleSymbolState matchedState;
    matchedState.moduleName = "ntoskrnl.exe";
    matchedState.wanted = kWanted;
    matchedState.loaded = kSameBuild;
    matchedState.attempt = SymbolLoadAttempt::kFileLoaded;
    matchedState.match = SymbolMatch::kMatched;
    matchedState.cacheSource = SymbolCacheSource::kLocalDirectory;
    s.expect(mayReportFunctionName(matchedState) && mayReportSourceLine(matchedState),
             L"C-04 a matched PDB is allowed to produce a function name and line");
    s.expect(allowedAttribution(matchedState, true) == SymbolAttribution::kFunctionAndSourceLine,
             L"C-04 a matched PDB allows the full attribution level");

    const ModuleSymbolState kFreshState;
    s.expect(kFreshState.match == SymbolMatch::kNotAttempted &&
                 kFreshState.attempt == SymbolLoadAttempt::kNotAttempted &&
                 kFreshState.cacheSource == SymbolCacheSource::kUnknown,
             L"C-04 a default-constructed symbol state claims nothing");
    s.expect(!mayReportFunctionName(kFreshState),
             L"C-04 a default-constructed symbol state may not produce a function name");
    s.expect(allowedAttribution(kFreshState, false) == SymbolAttribution::kModuleOnly,
             L"C-04 a default-constructed symbol state allows only the module name");

    // Both FileNotFound and LoadFailed map to Absent, but the two remain distinguishable.
    s.expect(absentState.attempt != SymbolLoadAttempt::kLoadFailed,
             L"C-04 the load attempt keeps file-not-found apart from load-failed");
    s.expect(std::string(symbolLoadAttemptName(SymbolLoadAttempt::kLoadFailed)) == "LoadFailed" &&
                 std::string(symbolLoadAttemptName(SymbolLoadAttempt::kFileNotFound)) ==
                     "FileNotFound",
             L"C-04 the two Absent causes have distinct names for the report");

    // Name override (per branch).
    s.expect(std::string(symbolMatchName(SymbolMatch::kNotAttempted)) == "NotAttempted" &&
                 std::string(symbolMatchName(SymbolMatch::kAbsent)) == "Absent" &&
                 std::string(symbolMatchName(SymbolMatch::kWrongVersion)) == "WrongVersion" &&
                 std::string(symbolMatchName(SymbolMatch::kMatched)) == "Matched",
             L"C-04 every SymbolMatch state has a distinct name");
    s.expect(std::string(symbolCacheSourceName(SymbolCacheSource::kSymbolServer)) ==
                     "SymbolServer" &&
                 std::string(symbolCacheSourceName(SymbolCacheSource::kDumpEmbedded)) ==
                     "DumpEmbedded" &&
                 std::string(symbolCacheSourceName(SymbolCacheSource::kLocalCache)) == "LocalCache" &&
                 std::string(symbolCacheSourceName(SymbolCacheSource::kLocalDirectory)) ==
                     "LocalDirectory" &&
                 std::string(symbolCacheSourceName(SymbolCacheSource::kNotLoaded)) == "NotLoaded" &&
                 std::string(symbolCacheSourceName(SymbolCacheSource::kUnknown)) == "Unknown",
             L"C-04 every symbol cache source has a distinct name");
    s.expect(std::string(symbolAttributionName(SymbolAttribution::kModuleOnly)) == "ModuleOnly" &&
                 std::string(symbolAttributionName(SymbolAttribution::kFunctionPlusOffset)) ==
                     "FunctionPlusOffset",
             L"C-04 attribution levels have distinct names");

    // Network symbol download: all three prerequisites are required; none are enabled by default.
    {
        const SymbolServerPolicy kFresh;
        s.expect(decideSymbolServerFetch(kFresh) == SymbolServerDecision::kRejectNotEnabled,
                 L"C-04 network symbol download is off by default");

        SymbolServerPolicy enabled;
        enabled.userEnabled = true;
        s.expect(decideSymbolServerFetch(enabled) == SymbolServerDecision::kRejectNotCancellable,
                 L"C-04 an enabled but uncancellable symbol fetch is rejected");

        SymbolServerPolicy cancellable = enabled;
        cancellable.cancellable = true;
        s.expect(decideSymbolServerFetch(cancellable) == SymbolServerDecision::kRejectNoTimeBudget,
                 L"C-04 a symbol fetch without a time budget is rejected");

        SymbolServerPolicy byteBudgetOnly = cancellable;
        byteBudgetOnly.budget.maxBytes = OptionalU64::of(1ULL << 20U);
        s.expect(decideSymbolServerFetch(byteBudgetOnly) == SymbolServerDecision::kRejectNoTimeBudget,
                 L"C-04 a byte budget is not a time budget for a blocking symbol server");

        SymbolServerPolicy zeroTime = cancellable;
        zeroTime.budget.maxDurationNanos = OptionalU64::of(0ULL);
        s.expect(decideSymbolServerFetch(zeroTime) == SymbolServerDecision::kRejectNoTimeBudget,
                 L"C-04 a zero time budget is not a usable time limit");

        SymbolServerPolicy allowed = cancellable;
        allowed.budget.maxDurationNanos = OptionalU64::of(15ULL * 1000000000ULL);
        s.expect(decideSymbolServerFetch(allowed) == SymbolServerDecision::kAllow,
                 L"C-04 an enabled, cancellable, time-bounded symbol fetch is allowed");
        s.expect(allowed.budget.bounded(),
                 L"C-04 the allowed symbol fetch budget really is bounded");
        s.expect(std::string(symbolServerDecisionName(SymbolServerDecision::kAllow)) == "Allow",
                 L"C-04 symbol server decisions have stable names");
    }
}

// ---------------------------------------------------------------------------
// C-05 Stack and modules
// ---------------------------------------------------------------------------
StackFrame makeUnwoundFrame(std::uint64_t address, const char* moduleName) {
    StackFrame frame;
    frame.address = OptionalU64::of(address);
    frame.stackPointer = OptionalU64::of(address - 0x1000ULL);
    frame.moduleName = moduleName;
    frame.moduleBase = OptionalU64::of(address & ~0xFFFFULL);
    frame.offsetInModule = OptionalU64::of(address & 0xFFFFULL);
    frame.unwindState = UnwindState::kUnwound;
    return frame;
}

void testStackAndUnwind(Reporter& s) {
    // Four branches of the unwind state.
    s.expect(unwindStateIsTerminal(UnwindState::kTruncatedNoData) &&
                 unwindStateIsTerminal(UnwindState::kTruncatedCorrupt),
             L"C-05 both truncation states are terminal frame boundaries");
    s.expect(!unwindStateIsTerminal(UnwindState::kUnwound) &&
                 !unwindStateIsTerminal(UnwindState::kGuessed),
             L"C-05 unwound and guessed frames are not boundaries");
    s.expect(unwindStateIsTrustworthy(UnwindState::kUnwound),
             L"C-05 only an actually unwound frame is trustworthy");
    s.expect(!unwindStateIsTrustworthy(UnwindState::kGuessed) &&
                 !unwindStateIsTrustworthy(UnwindState::kTruncatedNoData) &&
                 !unwindStateIsTrustworthy(UnwindState::kTruncatedCorrupt),
             L"C-05 a guessed or truncated frame is never trustworthy");
    s.expect(std::string(unwindStateName(UnwindState::kTruncatedNoData)) == "TruncatedNoData" &&
                 std::string(unwindStateName(UnwindState::kTruncatedCorrupt)) ==
                     "TruncatedCorrupt" &&
                 std::string(unwindStateName(UnwindState::kGuessed)) == "Guessed" &&
                 std::string(unwindStateName(UnwindState::kUnwound)) == "Unwound",
             L"C-05 all four unwind states have distinct names");

    {
        const StackFrame kFresh;
        s.expect(kFresh.unwindState == UnwindState::kTruncatedNoData &&
                     kFresh.symbolMatch == SymbolMatch::kNotAttempted && !kFresh.argsComplete &&
                     !kFresh.attributionAmbiguous,
                 L"C-05 a default frame is a boundary with no symbols and no claims");
    }

    // Valid stack: trusted frame + unsigned frame + explicit truncation boundary.
    StackTrace trace;
    {
        StackFrame top = makeUnwoundFrame(0xFFFFF80312345678ULL, "ntoskrnl.exe");
        top.symbolMatch = SymbolMatch::kMatched;
        top.functionName = "KeBugCheckEx";
        top.functionOffset = OptionalU64::of(0x1CULL);
        top.sourceFile = "d:\\rs\\ke\\bugcheck.c";
        top.sourceLine = OptionalU64::of(1234ULL);
        top.availableArgs = {OptionalU64::of(0x7EULL), OptionalU64::of(0ULL)};
        top.argsComplete = true;
        trace.frames.push_back(top);

        StackFrame middle = makeUnwoundFrame(0xFFFFF8031999ABCDULL, "acme_filter.sys");
        middle.symbolMatch = SymbolMatch::kAbsent;
        middle.availableArgs = {OptionalU64::of(1ULL), OptionalU64::unset()};
        middle.argsComplete = false;  // Unknown arguments present, so completeness cannot be claimed.
        trace.frames.push_back(middle);

        StackFrame boundary;
        boundary.address = OptionalU64::of(0xFFFFF80311110000ULL);
        boundary.unwindState = UnwindState::kTruncatedNoData;
        trace.frames.push_back(boundary);
    }
    trace.outcome = CollectionOutcome::success();
    s.expect(validateStackTrace(trace) == StackValidation::kOk,
             L"C-05 a well-formed stack with an explicit boundary validates");
    s.expect(trace.unwoundCount() == 2U && trace.guessedCount() == 0U &&
                 trace.truncatedCount() == 1U,
             L"C-05 unwound, guessed and truncated frames are counted separately");

    // Truncate then splice frames = splice guessed frames.
    {
        StackTrace spliced = trace;
        spliced.frames.push_back(makeUnwoundFrame(0xFFFFF80300000000ULL, "guessed.sys"));
        s.expect(validateStackTrace(spliced) == StackValidation::kFramesAfterTruncation,
                 L"C-05 red line: appending frames after a truncation boundary is rejected");
    }

    // Function name / line number provided despite no matching symbol.
    {
        StackTrace bad = trace;
        bad.frames[1].functionName = "AcmeFilterDispatch";
        s.expect(validateStackTrace(bad) == StackValidation::kFunctionNameWithoutMatchedSymbols,
                 L"C-05 a function name without matched symbols is rejected");
    }
    {
        StackTrace bad = trace;
        bad.frames[1].symbolMatch = SymbolMatch::kWrongVersion;
        bad.frames[1].sourceLine = OptionalU64::of(77ULL);
        s.expect(validateStackTrace(bad) == StackValidation::kSourceLineWithoutMatchedSymbols,
                 L"C-05 red line: a wrong-version PDB may not contribute a source line to a frame");
    }
    {
        StackTrace bad = trace;
        bad.frames[1].symbolMatch = SymbolMatch::kAbsent;
        bad.frames[1].sourceFile = "guessed.c";
        s.expect(validateStackTrace(bad) == StackValidation::kSourceLineWithoutMatchedSymbols,
                 L"C-05 a source file without matched symbols is rejected too");
    }

    // Attribution ambiguity must be preserved; do not flatten it.
    // Ambiguity can only occur in frames with matching symbols: if there is no match, there should be zero candidates
    // (the assertion below enforces this). Hence, we use frames[0] (Matched) instead of frames[1] (Absent). The
    // original version incorrectly used an Absent frame to carry candidates, which itself constitutes invalid input.
    {
        StackTrace ambiguous = trace;
        ambiguous.frames[0].attributionAmbiguous = true;
        ambiguous.frames[0].candidateFunctions = {"AcmeInline"};
        s.expect(validateStackTrace(ambiguous) == StackValidation::kAmbiguityCollapsed,
                 L"C-05 declaring ambiguity while keeping one candidate is rejected");
        ambiguous.frames[0].candidateFunctions = {"AcmeInline", "AcmeOuter"};
        s.expect(validateStackTrace(ambiguous) == StackValidation::kOk,
                 L"C-05 ambiguity with at least two candidates is preserved and accepted");
    }

    // C-04 Red line applies equally to plurals: Function names resolved from a mismatched PDB version prefixed
    // with 'Candidate' are still writing mismatched symbols to the UI, just shifting from singular to plural.
    {
        StackTrace candidates = trace;
        candidates.frames[1].symbolMatch = SymbolMatch::kWrongVersion;
        candidates.frames[1].attributionAmbiguous = true;
        candidates.frames[1].candidateFunctions = {"AcmeStartIo", "AcmeCompleteIrp"};
        s.expect(validateStackTrace(candidates) ==
                     StackValidation::kCandidatesWithoutMatchedSymbols,
                 L"C-04 red line: a wrong-version PDB may not contribute candidate function names");
        candidates.frames[1].symbolMatch = SymbolMatch::kAbsent;
        s.expect(validateStackTrace(candidates) ==
                     StackValidation::kCandidatesWithoutMatchedSymbols,
                 L"C-04 candidates on a frame with no symbols at all are rejected the same way");
        candidates.frames[1].symbolMatch = SymbolMatch::kNotAttempted;
        s.expect(validateStackTrace(candidates) ==
                     StackValidation::kCandidatesWithoutMatchedSymbols,
                 L"C-04 candidates on a frame whose symbols were never attempted are rejected");
        candidates.frames[1].symbolMatch = SymbolMatch::kMatched;
        s.expect(validateStackTrace(candidates) == StackValidation::kOk,
                 L"C-05 two candidates on a matched frame are preserved and accepted");
    }

    // Function-relative offsets are invalid if the function name cannot be resolved: without a function name, there is no 'function-relative offset'.
    {
        StackTrace offsetOnly = trace;
        offsetOnly.frames[1].symbolMatch = SymbolMatch::kAbsent;
        offsetOnly.frames[1].functionOffset = OptionalU64::of(0x40ULL);
        s.expect(validateStackTrace(offsetOnly) ==
                     StackValidation::kFunctionNameWithoutMatchedSymbols,
                 L"C-04 a function-relative offset without matched symbols is rejected too");
    }

    // Claims completeness despite incomplete arguments.
    {
        StackTrace bad = trace;
        bad.frames[1].argsComplete = true;
        s.expect(validateStackTrace(bad) == StackValidation::kIncompleteArgumentsClaimedComplete,
                 L"C-05 claiming complete arguments while one is unknown is rejected");
        s.expect(!bad.frames[1].availableArgs[1].present,
                 L"C-05 an unknown argument stays unset instead of being filled with zero");
    }

    // Pure stack scan result: valid, but no frame is trustworthy.
    {
        StackTrace guessed;
        for (std::uint64_t index = 0; index < 5U; ++index) {
            StackFrame frame = makeUnwoundFrame(0xFFFFF80300010000ULL + index * 0x100ULL,
                                                "unknown.sys");
            frame.unwindState = UnwindState::kGuessed;
            guessed.frames.push_back(frame);
        }
        s.expect(validateStackTrace(guessed) == StackValidation::kOk,
                 L"C-05 a scan-only stack is structurally valid");
        s.expect(guessed.unwoundCount() == 0U && guessed.guessedCount() == 5U,
                 L"C-05 a scan-only stack reports zero unwound frames so the UI cannot call it a call stack");
    }

    // Corrupted truncation: distinct from 'no data' as a boundary condition.
    {
        StackTrace corrupt;
        corrupt.frames.push_back(makeUnwoundFrame(0xFFFFF80312340000ULL, "ntoskrnl.exe"));
        StackFrame boundary;
        boundary.unwindState = UnwindState::kTruncatedCorrupt;
        corrupt.frames.push_back(boundary);
        s.expect(validateStackTrace(corrupt) == StackValidation::kOk,
                 L"C-05 a corrupt-truncation boundary is a valid terminal frame");
        s.expect(corrupt.frames[1].unwindState != UnwindState::kTruncatedNoData,
                 L"C-05 corrupt truncation stays distinct from missing-data truncation");
    }

    {
        const StackTrace kEmpty;
        s.expect(validateStackTrace(kEmpty) == StackValidation::kOk &&
                     kEmpty.unwoundCount() == 0U && kEmpty.guessedCount() == 0U,
                 L"C-05 an empty stack is valid and claims no frames");
        s.expect(kEmpty.outcome.status == CollectionStatus::kNotCollected,
                 L"C-05 a default stack trace has not been collected");
    }

    s.expect(std::string(stackValidationName(StackValidation::kOk)) == "Ok" &&
                 std::string(stackValidationName(StackValidation::kFramesAfterTruncation)) ==
                     "FramesAfterTruncation" &&
                 std::string(stackValidationName(
                     StackValidation::kIncompleteArgumentsClaimedComplete)) ==
                     "IncompleteArgumentsClaimedComplete" &&
                 std::string(stackValidationName(StackValidation::kAmbiguityCollapsed)) ==
                     "AmbiguityCollapsed" &&
                 std::string(stackValidationName(
                     StackValidation::kCandidatesWithoutMatchedSymbols)) ==
                     "CandidatesWithoutMatchedSymbols" &&
                 std::string(stackValidationName(
                     StackValidation::kFunctionNameWithoutMatchedSymbols)) !=
                     std::string(stackValidationName(
                         StackValidation::kCandidatesWithoutMatchedSymbols)),
             L"C-05 every stack validation verdict has a distinct name");
}

// ---------------------------------------------------------------------------
// C-06 Suspicious module explanation
// ---------------------------------------------------------------------------
ModuleEvidenceItem makeEvidence(ModuleEvidenceKind kind,
                                const char* moduleName,
                                UnwindState frameState,
                                std::uint64_t frameIndex) {
    ModuleEvidenceItem item;
    item.kind = kind;
    item.moduleName = moduleName;
    item.frameUnwindState = frameState;
    item.frameIndex = OptionalU64::of(frameIndex);
    item.detail = "raw text from the dump";
    return item;
}

void testSuspectExplanation(Reporter& s) {
    s.expect(isWellKnownSystemModuleName("ntoskrnl.exe"),
             L"C-06 ntoskrnl.exe is recognized as a well-known system module");
    s.expect(isWellKnownSystemModuleName("\\SystemRoot\\system32\\ntoskrnl.exe"),
             L"C-06 a full NT path to ntoskrnl is still recognized");
    s.expect(isWellKnownSystemModuleName("C:/Windows/System32/HAL.DLL"),
             L"C-06 the system module check folds ASCII case and both separators");
    s.expect(!isWellKnownSystemModuleName("acme_filter.sys"),
             L"C-06 a third-party driver is not a well-known system module");
    s.expect(!isWellKnownSystemModuleName("ntoskrnl.exe.evil.sys"),
             L"C-06 a look-alike name is not treated as the system module");
    s.expect(!isWellKnownSystemModuleName(""),
             L"C-06 an empty module name is not a system module");

    // A default-constructed group must not yield any clues.
    {
        const ModuleEvidenceGroup kFresh;
        s.expect(classifyLead(kFresh) == InvestigationLead::kUndetermined,
                 L"C-06 a default-constructed evidence group yields Undetermined");
        s.expect(kFresh.evidenceCount() == 0U,
                 L"C-06 a default-constructed evidence group holds no evidence");
    }

    // The three types of evidence are stored separately in groups.
    {
        std::vector<ModuleEvidenceItem> items;
        items.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "acme_filter.sys",
                                     UnwindState::kUnwound, 2U));
        items.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule, "acme_filter.sys",
                                     UnwindState::kUnwound, 0U));
        items.push_back(makeEvidence(ModuleEvidenceKind::kVerifierReported, "acme_filter.sys",
                                     UnwindState::kUnwound, 0U));
        items.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "NTOSKRNL.EXE",
                                     UnwindState::kUnwound, 1U));
        items.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "ntoskrnl.exe",
                                     UnwindState::kUnwound, 3U));
        const std::vector<ModuleEvidenceGroup> kGroups = groupModuleEvidence(items);
        s.expect(kGroups.size() == 2U,
                 L"C-06 evidence is grouped per module and ASCII case variants merge");
        std::size_t acmeIndex = kGroups.size();
        std::size_t kernelIndex = kGroups.size();
        for (std::size_t index = 0; index < kGroups.size(); ++index) {
            if (kGroups[index].moduleKey == "acme_filter.sys") {
                acmeIndex = index;
            }
            if (kGroups[index].moduleKey == "ntoskrnl.exe") {
                kernelIndex = index;
            }
        }
        s.expect(acmeIndex < kGroups.size() && kernelIndex < kGroups.size(),
                 L"C-06 both expected module groups are present with lowercase keys");
        if (acmeIndex < kGroups.size() && kernelIndex < kGroups.size()) {
            const ModuleEvidenceGroup& acme = kGroups[acmeIndex];
            s.expect(acme.onStack.size() == 1U && acme.faultingIp.size() == 1U &&
                         acme.verifier.size() == 1U,
                     L"C-06 the three evidence kinds stay in three separate lists");
            s.expect(acme.evidenceCount() == 3U,
                     L"C-06 the evidence count adds up across the three lists");
            s.expect(!acme.isWellKnownSystemModule,
                     L"C-06 a third-party driver group is not flagged as a system module");
            s.expect(acme.onStack[0].frameIndex == OptionalU64::of(2U),
                     L"C-06 each evidence item keeps the frame it came from");
            s.expect(acme.onStack[0].detail == "raw text from the dump",
                     L"C-06 the raw detail text is kept verbatim, not rewritten");

            const ModuleEvidenceGroup& kernel = kGroups[kernelIndex];
            s.expect(kernel.onStack.size() == 2U,
                     L"C-06 both case spellings of ntoskrnl land in the same group");
            s.expect(kernel.isWellKnownSystemModule,
                     L"C-06 the ntoskrnl group is flagged as a well-known system module");
            s.expect(kernel.moduleName == "NTOSKRNL.EXE",
                     L"C-06 the display name keeps the original spelling of the first occurrence");
        }
    }

    // Five branches of classifyLead.
    // Each group explicitly provides a moduleKey: Groups produced by groupModuleEvidence always have a key; groups without
    // a key have no identity, and classifyLead will only respond "Unable to determine" for them (see the section below).
    {
        ModuleEvidenceGroup thirdPartyStack;
        thirdPartyStack.moduleName = "acme_filter.sys";
        thirdPartyStack.moduleKey = "acme_filter.sys";
        thirdPartyStack.onStack.push_back(makeEvidence(ModuleEvidenceKind::kOnStack,
                                                       "acme_filter.sys",
                                                       UnwindState::kUnwound, 2U));
        s.expect(classifyLead(thirdPartyStack) == InvestigationLead::kStackPresenceOnly,
                 L"C-06 a third-party module on a trustworthy frame is a weak lead only");

        ModuleEvidenceGroup guessedOnly;
        guessedOnly.moduleName = "acme_filter.sys";
        guessedOnly.moduleKey = "acme_filter.sys";
        guessedOnly.onStack.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "acme_filter.sys",
                                                   UnwindState::kGuessed, 9U));
        s.expect(classifyLead(guessedOnly) == InvestigationLead::kUndetermined,
                 L"C-06 a module seen only in scan-guessed frames is not a lead at all");

        ModuleEvidenceGroup faulting;
        faulting.moduleName = "acme_filter.sys";
        faulting.moduleKey = "acme_filter.sys";
        faulting.faultingIp.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule,
                                                   "acme_filter.sys", UnwindState::kUnwound, 0U));
        s.expect(classifyLead(faulting) == InvestigationLead::kFaultingIpAttributed,
                 L"C-06 a faulting IP inside a third-party module is an actionable lead");

        ModuleEvidenceGroup verifier;
        verifier.moduleName = "acme_filter.sys";
        verifier.moduleKey = "acme_filter.sys";
        verifier.verifier.push_back(makeEvidence(ModuleEvidenceKind::kVerifierReported,
                                                  "acme_filter.sys", UnwindState::kUnwound, 0U));
        s.expect(classifyLead(verifier) == InvestigationLead::kVerifierNamed,
                 L"C-06 a Verifier report is the strongest lead");

        ModuleEvidenceGroup systemStack;
        systemStack.moduleName = "ntoskrnl.exe";
        systemStack.moduleKey = "ntoskrnl.exe";
        systemStack.isWellKnownSystemModule = true;
        systemStack.onStack.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "ntoskrnl.exe",
                                                   UnwindState::kUnwound, 0U));
        s.expect(classifyLead(systemStack) == InvestigationLead::kSystemModuleOnly,
                 L"C-06 red line: ntoskrnl on the stack is explicitly not a lead");

        ModuleEvidenceGroup systemFaulting;
        systemFaulting.moduleName = "ntoskrnl.exe";
        systemFaulting.moduleKey = "ntoskrnl.exe";
        systemFaulting.isWellKnownSystemModule = true;
        systemFaulting.faultingIp.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule,
                                                          "ntoskrnl.exe", UnwindState::kUnwound, 0U));
        s.expect(classifyLead(systemFaulting) == InvestigationLead::kSystemModuleOnly,
                 L"C-06 red line: a faulting IP inside ntoskrnl is not automatically the cause");
    }

    // Faulty IP evidence's own precondition: If a frame is deemed "self-contradictory" (TruncatedCorrupt) but is still
    // used to upgrade a third-party driver into a viable lead, it draws conclusions from data one does not trust.
    // The onStack branch has always had this threshold; the faultingIp branch previously had none.
    {
        ModuleEvidenceGroup corruptFrame;
        corruptFrame.moduleName = "acme_filter.sys";
        corruptFrame.moduleKey = "acme_filter.sys";
        corruptFrame.faultingIp.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule,
                                                       "acme_filter.sys",
                                                       UnwindState::kTruncatedCorrupt, 0U));
        s.expect(classifyLead(corruptFrame) == InvestigationLead::kUndetermined,
                 L"C-06 a faulting IP read off a self-contradictory frame is not an actionable lead");

        ModuleEvidenceGroup noData = corruptFrame;
        noData.faultingIp[0].frameUnwindState = UnwindState::kTruncatedNoData;
        s.expect(classifyLead(noData) == InvestigationLead::kUndetermined,
                 L"C-06 a faulting IP with no frame data behind it is not an actionable lead");

        ModuleEvidenceGroup guessedFrame = corruptFrame;
        guessedFrame.faultingIp[0].frameUnwindState = UnwindState::kGuessed;
        s.expect(classifyLead(guessedFrame) == InvestigationLead::kUndetermined,
                 L"C-06 a faulting IP guessed from a stack scan is not an actionable lead");

        // The actual faulting IP comes from the trap frame / context record, independent of unwind quality.
        // This bit must be true to skip inspection — default is false, so inspection is not skipped by default.
        ModuleEvidenceGroup fromContext = corruptFrame;
        fromContext.faultingIp[0].ipFromContextRecord = true;
        s.expect(classifyLead(fromContext) == InvestigationLead::kFaultingIpAttributed,
                 L"C-06 a faulting IP taken from the context record is an actionable lead");
        s.expect(!ModuleEvidenceItem{}.ipFromContextRecord,
                 L"C-06 evidence does not claim a context-record IP by default");

        // An invalid fault IP does not mean the group disappears: if there are still trusted frames on the stack, it remains a weak clue.
        ModuleEvidenceGroup alsoOnStack = corruptFrame;
        alsoOnStack.onStack.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "acme_filter.sys",
                                                   UnwindState::kUnwound, 3U));
        s.expect(classifyLead(alsoOnStack) == InvestigationLead::kStackPresenceOnly,
                 L"C-06 an unfounded faulting IP falls back to the stack evidence, not to nothing");
    }

    // Modules without names yield no clues. An empty module name passed through groupModuleEvidence produces
    // a group with an empty key, meaning the 'verifiable clues' in that group have no verifiable object.
    {
        std::vector<ModuleEvidenceItem> nameless;
        nameless.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule, "",
                                        UnwindState::kUnwound, 0U));
        const std::vector<ModuleEvidenceGroup> kGroups = groupModuleEvidence(nameless);
        s.expect(kGroups.size() == 1U && kGroups[0].moduleKey.empty(),
                 L"C-06 an empty module name still forms exactly one keyless group");
        s.expect(kGroups.size() == 1U && classifyLead(kGroups[0]) == InvestigationLead::kUndetermined,
                 L"C-06 red line: a module with no name at all never becomes an actionable lead");
        const SuspectReport kReport =
            buildSuspectReport(kGroups, CollectionOutcome::success());
        s.expect(kReport.conclusion == AnalysisConclusion::kIndeterminate,
                 L"C-06 a nameless module group does not push the report to an actionable conclusion");
    }

    // No observation results in NoEvidence, and even if a verifier group is passed, it is downgraded to Undetermined.
    {
        std::vector<ModuleEvidenceGroup> groups;
        ModuleEvidenceGroup verifier;
        verifier.moduleName = "acme_filter.sys";
        verifier.moduleKey = "acme_filter.sys";
        verifier.verifier.push_back(makeEvidence(ModuleEvidenceKind::kVerifierReported,
                                                  "acme_filter.sys", UnwindState::kUnwound, 0U));
        groups.push_back(verifier);

        CollectionOutcome noStack = CollectionOutcome::notCollected();
        const SuspectReport kReport = buildSuspectReport(groups, noStack);
        s.expect(kReport.conclusion == AnalysisConclusion::kNoEvidence,
                 L"C-06 red line: no stack observation yields NoEvidence, never a verdict");
        s.expect(kReport.leads.size() == 1U &&
                     kReport.leads[0].lead == InvestigationLead::kUndetermined,
                 L"C-06 red line: without an observation even a Verifier group stays Undetermined");
        s.expect(kReport.limitationKeys.size() == 1U &&
                     kReport.limitationKeys[0] == "dump.suspect.no_stack_observation",
                 L"C-06 the missing observation is stated explicitly in the limitations");
    }

    // Only ntoskrnl: cannot determine.
    {
        std::vector<ModuleEvidenceGroup> groups;
        ModuleEvidenceGroup kernel;
        kernel.moduleName = "ntoskrnl.exe";
        kernel.moduleKey = "ntoskrnl.exe";
        kernel.isWellKnownSystemModule = true;
        kernel.onStack.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "ntoskrnl.exe",
                                              UnwindState::kUnwound, 0U));
        kernel.faultingIp.push_back(makeEvidence(ModuleEvidenceKind::kFaultingIpModule,
                                                  "ntoskrnl.exe", UnwindState::kUnwound, 0U));
        groups.push_back(kernel);

        const SuspectReport kReport = buildSuspectReport(groups, CollectionOutcome::success());
        s.expect(kReport.conclusion == AnalysisConclusion::kIndeterminate,
                 L"C-06 an ntoskrnl-only dump concludes Indeterminate, not a root cause");
        s.expect(kReport.conclusion != AnalysisConclusion::kNoDifferenceObserved,
                 L"C-06 a crash dump never concludes no-difference-observed");
        bool sawSystemOnlyKey = false;
        bool sawInsufficientKey = false;
        for (const std::string& key : kReport.limitationKeys) {
            sawSystemOnlyKey = sawSystemOnlyKey || key == "dump.suspect.system_module_only";
            sawInsufficientKey = sawInsufficientKey || key == "dump.suspect.insufficient_evidence";
        }
        s.expect(sawSystemOnlyKey && sawInsufficientKey,
                 L"C-06 the report states both that evidence is insufficient and why");
        s.expect(kReport.leads[0].lead == InvestigationLead::kSystemModuleOnly,
                 L"C-06 the ntoskrnl lead is classified as system-module-only");
    }

    // Third-party drivers flagged by Verifier: potential leads.
    {
        std::vector<ModuleEvidenceItem> items;
        items.push_back(makeEvidence(ModuleEvidenceKind::kVerifierReported, "acme_filter.sys",
                                     UnwindState::kUnwound, 0U));
        items.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "ntoskrnl.exe",
                                     UnwindState::kUnwound, 0U));
        const SuspectReport kReport =
            buildSuspectReport(groupModuleEvidence(items), CollectionOutcome::success());
        s.expect(kReport.conclusion == AnalysisConclusion::kDifferenceObserved,
                 L"C-06 a Verifier-named third-party driver yields an actionable conclusion");
        s.expect(kReport.leads.size() == 2U,
                 L"C-06 both the named driver and the system module keep their own entries");
    }

    // Partial collection must be explicitly stated within the limits.
    {
        std::vector<ModuleEvidenceItem> items;
        items.push_back(makeEvidence(ModuleEvidenceKind::kOnStack, "acme_filter.sys",
                                     UnwindState::kUnwound, 1U));
        CollectionOutcome partial;
        partial.status = CollectionStatus::kPartial;
        const SuspectReport kReport = buildSuspectReport(groupModuleEvidence(items), partial);
        bool sawPartialKey = false;
        bool sawStackOnlyKey = false;
        for (const std::string& key : kReport.limitationKeys) {
            sawPartialKey = sawPartialKey || key == "dump.suspect.stack_partial";
            sawStackOnlyKey = sawStackOnlyKey || key == "dump.suspect.stack_presence_only";
        }
        s.expect(sawPartialKey && sawStackOnlyKey,
                 L"C-06 a partial stack collection is disclosed alongside the weak-lead note");
        s.expect(kReport.conclusion == AnalysisConclusion::kIndeterminate,
                 L"C-06 stack presence alone does not become an actionable conclusion");
    }

    // Empty evidence set with observations: explicitly state 'no module evidence'.
    {
        const SuspectReport kReport =
            buildSuspectReport(std::vector<ModuleEvidenceGroup>{}, CollectionOutcome::success());
        bool sawNoModuleKey = false;
        for (const std::string& key : kReport.limitationKeys) {
            sawNoModuleKey = sawNoModuleKey || key == "dump.suspect.no_module_evidence";
        }
        s.expect(sawNoModuleKey,
                 L"C-06 an empty but observed evidence set is stated, not silently positive");
        s.expect(kReport.conclusion == AnalysisConclusion::kIndeterminate,
                 L"C-06 an empty evidence set is Indeterminate, not NoDifferenceObserved");
    }

    s.expect(std::string(investigationLeadName(InvestigationLead::kUndetermined)) ==
                     "Undetermined" &&
                 std::string(investigationLeadName(InvestigationLead::kSystemModuleOnly)) ==
                     "SystemModuleOnly" &&
                 std::string(investigationLeadName(InvestigationLead::kStackPresenceOnly)) ==
                     "StackPresenceOnly" &&
                 std::string(investigationLeadName(InvestigationLead::kFaultingIpAttributed)) ==
                     "FaultingIpAttributed" &&
                 std::string(investigationLeadName(InvestigationLead::kVerifierNamed)) ==
                     "VerifierNamed",
             L"C-06 every investigation lead level has a distinct name");
    s.expect(std::string(moduleEvidenceKindName(ModuleEvidenceKind::kOnStack)) == "OnStack" &&
                 std::string(moduleEvidenceKindName(ModuleEvidenceKind::kFaultingIpModule)) ==
                     "FaultingIpModule" &&
                 std::string(moduleEvidenceKindName(ModuleEvidenceKind::kVerifierReported)) ==
                     "VerifierReported",
             L"C-06 the three evidence kinds have distinct names");

    // Check the wording of the privilege escalation field: the lead level name must not contain digits
    // or percent signs, otherwise it can easily be misread as "uncalibrated responsibility ratio".
    {
        bool clean = true;
        for (const InvestigationLead kLead :
             {InvestigationLead::kUndetermined, InvestigationLead::kSystemModuleOnly,
              InvestigationLead::kStackPresenceOnly, InvestigationLead::kFaultingIpAttributed,
              InvestigationLead::kVerifierNamed}) {
            const std::string kName = investigationLeadName(kLead);
            for (const char kValue : kName) {
                if ((kValue >= '0' && kValue <= '9') || kValue == '%') {
                    clean = false;
                }
            }
        }
        s.expect(clean,
                 L"C-06 lead levels carry no digits or percent signs, so they cannot read as blame shares");
    }
}

// ---------------------------------------------------------------------------
// C-07 Missing memory boundary
// ---------------------------------------------------------------------------
void testContentAvailability(Reporter& s) {
    {
        const DumpContentAvailability kFresh;
        bool allUnknown = true;
        for (const ContentCategory kCategory :
             {ContentCategory::kIrpObjects, ContentCategory::kLockObjects,
              ContentCategory::kFullProcessSpace, ContentCategory::kPoolMemory,
              ContentCategory::kKernelModuleList, ContentCategory::kThreadStacks,
              ContentCategory::kPhysicalMemory}) {
            allUnknown = allUnknown && kFresh.presenceOf(kCategory) == ContentPresence::kUnknown;
        }
        s.expect(allUnknown,
                 L"C-07 a default-constructed availability table is entirely Unknown");
        s.expect(queryContent(kFresh, ContentCategory::kIrpObjects) ==
                     ContentQueryResult::kUnknownAvailability,
                 L"C-07 an unjudged category answers UnknownAvailability, never 'not there'");
    }

    // small dump: Querying IRPs must return 'dump not included'.
    {
        const DumpContentAvailability kSmall = deriveAvailabilityFromKind(DumpKind::kKernelSmall);
        s.expect(queryContent(kSmall, ContentCategory::kIrpObjects) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 asking a small dump for IRP objects answers 'not included in dump'");
        s.expect(queryContent(kSmall, ContentCategory::kLockObjects) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 asking a small dump for lock objects answers 'not included in dump'");
        s.expect(queryContent(kSmall, ContentCategory::kFullProcessSpace) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 a small dump does not contain a full process address space");
        s.expect(queryContent(kSmall, ContentCategory::kPoolMemory) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 a small dump does not contain pool memory");
        s.expect(queryContent(kSmall, ContentCategory::kPhysicalMemory) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 a small dump does not contain physical memory");
        s.expect(queryContent(kSmall, ContentCategory::kKernelModuleList) ==
                     ContentQueryResult::kUnknownAvailability,
                 L"C-07 a small dump's module list is Unknown until actually parsed, never assumed present");
        s.expect(queryContent(kSmall, ContentCategory::kThreadStacks) ==
                     ContentQueryResult::kUnknownAvailability,
                 L"C-07 a small dump's thread stacks are Unknown until actually parsed");
    }

    // kernel memory dump: No item can be determined as 'definitely included' based solely on the type.
    {
        const DumpContentAvailability kMemory = deriveAvailabilityFromKind(DumpKind::kKernelMemory);
        bool allUnknown = true;
        for (const ContentCategory kCategory :
             {ContentCategory::kIrpObjects, ContentCategory::kLockObjects,
              ContentCategory::kFullProcessSpace, ContentCategory::kPoolMemory,
              ContentCategory::kKernelModuleList, ContentCategory::kThreadStacks,
              ContentCategory::kPhysicalMemory}) {
            allUnknown = allUnknown && queryContent(kMemory, kCategory) ==
                                           ContentQueryResult::kUnknownAvailability;
        }
        s.expect(allUnknown,
                 L"C-07 a kernel memory dump promises nothing by type alone; everything stays Unknown");
    }

    // User-mode dump: kernel objects are definitely not included.
    {
        const DumpContentAvailability kUser = deriveAvailabilityFromKind(DumpKind::kUserMinidump);
        s.expect(queryContent(kUser, ContentCategory::kIrpObjects) ==
                         ContentQueryResult::kNotIncludedInDump &&
                     queryContent(kUser, ContentCategory::kPoolMemory) ==
                         ContentQueryResult::kNotIncludedInDump &&
                     queryContent(kUser, ContentCategory::kKernelModuleList) ==
                         ContentQueryResult::kNotIncludedInDump,
                 L"C-07 a user minidump reports kernel-only categories as not included");
        s.expect(queryContent(kUser, ContentCategory::kFullProcessSpace) ==
                     ContentQueryResult::kUnknownAvailability,
                 L"C-07 whether a user minidump has full memory depends on the writer flags");
    }

    // Unrecognized file: do not claim 'not included' due to parsing failure.
    {
        const DumpContentAvailability kUnknown = deriveAvailabilityFromKind(DumpKind::kNotADump);
        const DumpContentAvailability kUnsupported =
            deriveAvailabilityFromKind(DumpKind::kUnsupported);
        s.expect(queryContent(kUnknown, ContentCategory::kIrpObjects) ==
                         ContentQueryResult::kUnknownAvailability &&
                     queryContent(kUnsupported, ContentCategory::kPoolMemory) ==
                         ContentQueryResult::kUnknownAvailability,
                 L"C-07 an unparsed file never claims that content is absent");
    }

    // All three explicitly set presence states can be distinguished via query.
    {
        DumpContentAvailability manual;
        manual.set(ContentCategory::kIrpObjects, ContentPresence::kIncluded);
        manual.set(ContentCategory::kLockObjects, ContentPresence::kNotParsable);
        manual.set(ContentCategory::kPoolMemory, ContentPresence::kNotIncluded);
        s.expect(queryContent(manual, ContentCategory::kIrpObjects) ==
                     ContentQueryResult::kAvailable,
                 L"C-07 an explicitly present category is queryable");
        s.expect(queryContent(manual, ContentCategory::kLockObjects) ==
                     ContentQueryResult::kNotParsableHere,
                 L"C-07 'present but unparsable' stays distinct from 'not in the dump'");
        s.expect(queryContent(manual, ContentCategory::kPoolMemory) ==
                     ContentQueryResult::kNotIncludedInDump,
                 L"C-07 an explicitly absent category answers 'not included in dump'");
        s.expect(manual.presenceOf(ContentCategory::kThreadStacks) == ContentPresence::kUnknown,
                 L"C-07 categories that were never set stay Unknown");
    }

    // Name coverage.
    s.expect(std::string(contentPresenceName(ContentPresence::kUnknown)) == "Unknown" &&
                 std::string(contentPresenceName(ContentPresence::kNotIncluded)) == "NotIncluded" &&
                 std::string(contentPresenceName(ContentPresence::kNotParsable)) == "NotParsable" &&
                 std::string(contentPresenceName(ContentPresence::kIncluded)) == "Included",
             L"C-07 all four presence states have distinct names");
    s.expect(std::string(contentQueryResultName(ContentQueryResult::kNotIncludedInDump)) ==
                     "NotIncludedInDump" &&
                 std::string(contentQueryResultName(ContentQueryResult::kNotParsableHere)) ==
                     "NotParsableHere" &&
                 std::string(contentQueryResultName(ContentQueryResult::kUnknownAvailability)) ==
                     "UnknownAvailability" &&
                 std::string(contentQueryResultName(ContentQueryResult::kAvailable)) == "Available",
             L"C-07 all four query results have distinct names");
    s.expect(std::string(contentCategoryName(ContentCategory::kIrpObjects)) == "IrpObjects" &&
                 std::string(contentCategoryName(ContentCategory::kPhysicalMemory)) ==
                     "PhysicalMemory",
             L"C-07 content categories have stable names for the report");

    // Dump external supplements must be explicitly declared.
    {
        const ExternalSupplement kNone;
        s.expect(supplementDisclosed(kNone),
                 L"C-07 not using external data needs no disclosure");

        ExternalSupplement undisclosed;
        undisclosed.used = true;
        s.expect(!supplementDisclosed(undisclosed),
                 L"C-07 red line: filling gaps from outside the dump without disclosure is rejected");

        ExternalSupplement wrongOrigin = undisclosed;
        wrongOrigin.disclosureKey = "dump.supplement.disk_image";
        wrongOrigin.source.collectorId = "disk.image.reader";
        wrongOrigin.source.origin = SourceOrigin::kLiveKernel;
        s.expect(!supplementDisclosed(wrongOrigin),
                 L"C-07 external supplements must be labelled as coming from an external file");

        ExternalSupplement disclosed = wrongOrigin;
        disclosed.source.origin = SourceOrigin::kExternalFile;
        s.expect(supplementDisclosed(disclosed),
                 L"C-07 a disclosed external supplement with a proper source is accepted");
    }
}

// ---------------------------------------------------------------------------
// C-08: Timeout, cancellation, and isolation.
// ---------------------------------------------------------------------------
void testInterruptionAndHelpers(Reporter& s) {
    // Only terminate helpers owned by this module.
    {
        const HelperOwnership kFresh;
        s.expect(decideHelperTermination(kFresh, "dump.facts") == TerminateDecision::kRejectNotOwned,
                 L"C-08 red line: a default helper record is never allowed to be terminated");

        HelperOwnership foreign;
        foreign.startedByThisModule = true;
        foreign.ownerModuleId = "someone.else";
        foreign.helperId = "helper-1";
        s.expect(decideHelperTermination(foreign, "dump.facts") ==
                     TerminateDecision::kRejectOwnerMismatch,
                 L"C-08 red line: another module's helper is never terminated");

        HelperOwnership anonymous;
        anonymous.startedByThisModule = true;
        anonymous.ownerModuleId = "dump.facts";
        s.expect(decideHelperTermination(anonymous, "dump.facts") ==
                     TerminateDecision::kRejectNoHelperIdentity,
                 L"C-08 a helper with no instance id is not terminated by pid alone");

        HelperOwnership mine = anonymous;
        mine.helperId = "helper-7";
        mine.processId = OptionalU64::of(4242ULL);
        s.expect(decideHelperTermination(mine, "dump.facts") == TerminateDecision::kAllow,
                 L"C-08 this module's own identified helper may be terminated");
        s.expect(decideHelperTermination(mine, "") == TerminateDecision::kRejectOwnerMismatch,
                 L"C-08 an unnamed requester never gets termination rights");
    }

    s.expect(helperStateIsTerminal(HelperState::kExited) && helperStateIsTerminal(HelperState::kFailed),
             L"C-08 Exited and Failed are terminal helper states");
    s.expect(!helperStateIsTerminal(HelperState::kCancelling) &&
                 !helperStateIsTerminal(HelperState::kStalled) &&
                 !helperStateIsTerminal(HelperState::kDisconnected) &&
                 !helperStateIsTerminal(HelperState::kNotStarted) &&
                 !helperStateIsTerminal(HelperState::kStarting) &&
                 !helperStateIsTerminal(HelperState::kReady) &&
                 !helperStateIsTerminal(HelperState::kBusy),
             L"C-08 a cancelling or stalled helper is not terminal and may still hold resources");
    s.expect(std::string(helperStateName(HelperState::kCancelling)) == "Cancelling" &&
                 std::string(helperStateName(HelperState::kStalled)) == "Stalled" &&
                 std::string(helperStateName(HelperState::kDisconnected)) == "Disconnected",
             L"C-08 helper states have distinct names");
    s.expect(std::string(terminateDecisionName(TerminateDecision::kAllow)) == "Allow" &&
                 std::string(terminateDecisionName(TerminateDecision::kRejectNoHelperIdentity)) ==
                     "RejectNoHelperIdentity",
             L"C-08 termination decisions have distinct names");

    ScanBudget budget;
    budget.maxDurationNanos = OptionalU64::of(10ULL * 1000000000ULL);
    budget.maxItems = OptionalU64::of(5000ULL);

    // Timed out but retained partial results.
    {
        CoverageAccount coverage;
        coverage.succeeded = 120U;
        coverage.totalKnown = OptionalU64::of(4000ULL);
        const InterruptedResult kResult =
            buildInterruptedResult(BudgetStop::kTimeExhausted, HelperState::kBusy, budget, coverage,
                                   true);
        s.expect(kResult.outcome.status == CollectionStatus::kPartial,
                 L"C-08 a timed-out run that kept results is Partial");
        s.expect(kResult.coverage.limitHit &&
                     kResult.coverage.limit == OptionalU64::of(10ULL * 1000000000ULL),
                 L"C-08 the time budget that stopped the run is written into the account");
        s.expect(kResult.partialResultsRetained,
                 L"C-08 the partial results are marked as retained");
        s.expect(!kResult.coverage.fullyCovered(),
                 L"C-08 an interrupted run is never reported as fully covered");
        bool sawStopKey = false;
        for (const std::string& key : kResult.interruptionKeys) {
            sawStopKey = sawStopKey || key == "dump.interrupt.TimeExhausted";
        }
        s.expect(sawStopKey, L"C-08 the interruption reason is stated with a stable key");
    }

    // Timeout with no data collected: must not report Partial.
    {
        const InterruptedResult kResult =
            buildInterruptedResult(BudgetStop::kTimeExhausted, HelperState::kBusy, budget,
                                   CoverageAccount{}, false);
        s.expect(kResult.outcome.status == CollectionStatus::kTimeout,
                 L"C-08 red line: a timeout with zero results is Timeout, never Partial");
        s.expect(!statusCarriesObservation(kResult.outcome.status),
                 L"C-08 a zero-result timeout carries no observation for downstream conclusions");
        bool sawNoResultKey = false;
        for (const std::string& key : kResult.interruptionKeys) {
            sawNoResultKey = sawNoResultKey || key == "dump.interrupt.no_partial_results";
        }
        s.expect(sawNoResultKey, L"C-08 having no partial results at all is stated explicitly");
    }

    // Cancel.
    {
        CoverageAccount coverage;
        coverage.succeeded = 3U;
        const InterruptedResult kKept =
            buildInterruptedResult(BudgetStop::kCancelled, HelperState::kCancelling, budget, coverage,
                                   true);
        s.expect(kKept.outcome.status == CollectionStatus::kPartial,
                 L"C-08 a cancellation that kept results is Partial");
        s.expect(kKept.coverage.cancelled && !kKept.coverage.limitHit,
                 L"C-08 a cancellation is recorded as cancelled, not as hitting an unknown limit");
        bool sawCancellingKey = false;
        for (const std::string& key : kKept.interruptionKeys) {
            sawCancellingKey = sawCancellingKey || key == "dump.helper.cancelling";
        }
        s.expect(sawCancellingKey,
                 L"C-08 a helper still winding down is disclosed rather than reported as cleaned up");

        const InterruptedResult kEmpty =
            buildInterruptedResult(BudgetStop::kCancelled, HelperState::kCancelling, budget,
                                   CoverageAccount{}, false);
        s.expect(kEmpty.outcome.status == CollectionStatus::kNotCollected,
                 L"C-08 a cancellation before any result is NotCollected, never Partial");
    }

    // helper stalled / disconnected / failed.
    {
        const InterruptedResult kStalled =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kStalled, budget,
                                   CoverageAccount{}, true);
        s.expect(kStalled.outcome.status == CollectionStatus::kTimeout &&
                     kStalled.outcome.message == "dump.helper.stalled",
                 L"C-08 a stalled helper is reported as a timeout with its own reason");

        const InterruptedResult kDropped =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kDisconnected, budget,
                                   CoverageAccount{}, true);
        s.expect(kDropped.outcome.status == CollectionStatus::kError &&
                     kDropped.outcome.message == "dump.helper.disconnected",
                 L"C-08 a disconnected helper is an error distinct from a timeout");

        const InterruptedResult kFailed =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kFailed, budget,
                                   CoverageAccount{}, true);
        s.expect(kFailed.outcome.status == CollectionStatus::kError &&
                     kFailed.outcome.message == "dump.helper.failed",
                 L"C-08 a failed helper is reported as an error");
    }

    // Correct empty set: not interrupted, and indeed no result.
    // Prerequisite: the helper must be settled; only Ready and Exited count. Other states are described in the section below.
    {
        const InterruptedResult kClean =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kReady, budget,
                                   CoverageAccount{}, false);
        s.expect(kClean.outcome.status == CollectionStatus::kSuccess,
                 L"C-08 an uninterrupted run with genuinely nothing to report stays Success");
        s.expect(kClean.interruptionKeys.empty(),
                 L"C-08 an uninterrupted run reports no interruption keys");
        s.expect(!kClean.partialResultsRetained,
                 L"C-08 a correct empty set is distinguishable from retained partial results");

        const InterruptedResult kExited =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kExited, budget,
                                   CoverageAccount{}, false);
        s.expect(kExited.outcome.status == CollectionStatus::kSuccess,
                 L"C-08 a helper that finished and exited also yields a correct empty set");
    }

    // C-08 Red Line: If a helper has never started, is still starting, is still running, or is cancelling,
    // and no results are reported yet but Success is returned, it means 'no normal exit was observed'.
    // statusCarriesObservation will allow this, and downstream logic will conclude 'no differences found'.
    // stop==Continue only indicates that the budget has not been exhausted; it provides no information about whether the helper is running.
    {
        const HelperState kUnsettled[] = {HelperState::kNotStarted, HelperState::kStarting,
                                          HelperState::kBusy, HelperState::kCancelling};
        bool allNonObserving = true;
        bool allNotCollected = true;
        bool allDisclosed = true;
        for (const HelperState kState : kUnsettled) {
            const InterruptedResult kResult =
                buildInterruptedResult(BudgetStop::kContinue, kState, budget, CoverageAccount{},
                                       false);
            allNonObserving = allNonObserving && !statusCarriesObservation(kResult.outcome.status);
            allNotCollected =
                allNotCollected && kResult.outcome.status == CollectionStatus::kNotCollected;
            allDisclosed = allDisclosed && !kResult.interruptionKeys.empty();
        }
        s.expect(allNonObserving,
                 L"C-08 red line: a helper that never settled carries no observation for conclusions");
        s.expect(allNotCollected,
                 L"C-08 an unsettled helper with zero results is NotCollected, never Success");
        s.expect(allDisclosed,
                 L"C-08 an unsettled helper states why the run is incomplete");

        const InterruptedResult kNotStarted =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kNotStarted, budget,
                                   CoverageAccount{}, false);
        s.expect(kNotStarted.outcome.message == "dump.helper.not_started",
                 L"C-08 a helper that was never started says so instead of reporting success");
        bool sawNotStartedKey = false;
        for (const std::string& key : kNotStarted.interruptionKeys) {
            sawNotStartedKey = sawNotStartedKey || key == "dump.helper.not_started";
        }
        s.expect(sawNotStartedKey,
                 L"C-08 the never-started helper is disclosed with its own stable key");

        const InterruptedResult kBusy =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kBusy, budget,
                                   CoverageAccount{}, false);
        s.expect(kBusy.outcome.message == "dump.helper.still_running",
                 L"C-08 a helper still running is disclosed rather than reported as finished");

        // Still running but already has results: This is genuine partial data, not a full success.
        CoverageAccount someCoverage;
        someCoverage.succeeded = 7U;
        const InterruptedResult kBusyWithResults =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kBusy, budget, someCoverage,
                                   true);
        s.expect(kBusyWithResults.outcome.status == CollectionStatus::kPartial,
                 L"C-08 results held by a still-running helper are Partial, never a complete Success");
        s.expect(kBusyWithResults.partialResultsRetained,
                 L"C-08 the results a still-running helper already produced are retained");

        // Cancellation during cleanup with no result: neither Partial nor Success.
        const InterruptedResult kCancelling =
            buildInterruptedResult(BudgetStop::kContinue, HelperState::kCancelling, budget,
                                   CoverageAccount{}, false);
        bool sawCancellingKey = false;
        for (const std::string& key : kCancelling.interruptionKeys) {
            sawCancellingKey = sawCancellingKey || key == "dump.helper.cancelling";
        }
        s.expect(sawCancellingKey,
                 L"C-08 a helper winding down is disclosed even when the budget said continue");
    }

    // All nine branches of helperStateSettled are individually asserted. Expected values are manually written here, not derived from the function under test.
    s.expect(helperStateSettled(HelperState::kReady) && helperStateSettled(HelperState::kExited),
             L"C-08 only a ready or exited helper counts as settled");
    s.expect(!helperStateSettled(HelperState::kNotStarted) &&
                 !helperStateSettled(HelperState::kStarting) &&
                 !helperStateSettled(HelperState::kBusy) &&
                 !helperStateSettled(HelperState::kStalled) &&
                 !helperStateSettled(HelperState::kDisconnected) &&
                 !helperStateSettled(HelperState::kCancelling) &&
                 !helperStateSettled(HelperState::kFailed),
             L"C-08 every other helper state is unsettled and its result set is incomplete");
    s.expect(!helperStateIsTerminal(HelperState::kReady) && helperStateSettled(HelperState::kReady),
             L"C-08 settled and terminal are two different questions about a helper");

    // Budget exhausted for count/bytes/pages with no results.
    {
        const InterruptedResult kItems =
            buildInterruptedResult(BudgetStop::kItemsExhausted, HelperState::kBusy, budget,
                                   CoverageAccount{}, false);
        s.expect(kItems.outcome.status == CollectionStatus::kError,
                 L"C-08 an item budget exhausted before any result is an error, not Partial");
        const InterruptedResult kBytes =
            buildInterruptedResult(BudgetStop::kBytesExhausted, HelperState::kBusy, budget,
                                   CoverageAccount{}, true);
        s.expect(kBytes.outcome.status == CollectionStatus::kPartial && kBytes.coverage.limitHit,
                 L"C-08 a byte budget exhausted with results kept is Partial with limitHit");
        const InterruptedResult kPages =
            buildInterruptedResult(BudgetStop::kPagesExhausted, HelperState::kBusy, budget,
                                   CoverageAccount{}, true);
        s.expect(kPages.outcome.status == CollectionStatus::kPartial,
                 L"C-08 a page budget exhausted with results kept is Partial");
    }

    {
        const InterruptedResult kFresh;
        s.expect(kFresh.stop == BudgetStop::kContinue &&
                     kFresh.helperState == HelperState::kNotStarted &&
                     !kFresh.partialResultsRetained,
                 L"C-08 a default interrupted result claims nothing was started or retained");
    }
}

// ---------------------------------------------------------------------------
// C-09: Untrusted paths and output.
// ---------------------------------------------------------------------------
void testUntrustedTextAndCommands(Reporter& s) {
    // Expected value is manually written byte-by-byte, not derived from the production function.
    s.expect(escapeForReport("<script>alert('x')</script>") ==
                 "&lt;script&gt;alert(&#39;x&#39;)&lt;/script&gt;",
             L"C-09 a script tag is fully escaped into text");
    s.expect(escapeForReport("A&B<C>D\"E'F") == "A&amp;B&lt;C&gt;D&quot;E&#39;F",
             L"C-09 all five HTML-significant characters are escaped");
    s.expect(escapeForReport("evil\";DEL /F /Q C:\\ &whoami") ==
                 "evil&quot;;DEL /F /Q C:\\ &amp;whoami",
             L"C-09 quotes and ampersands in a shell-looking module name are escaped as text");
    s.expect(escapeForReport("<exec cmd=\"!process 0 0\">") ==
                 "&lt;exec cmd=&quot;!process 0 0&quot;&gt;",
             L"C-09 a DML exec tag is escaped into inert text");
    s.expect(escapeForReport("..\\..\\Windows\\System32\\config\\SAM") ==
                 "..\\..\\Windows\\System32\\config\\SAM",
             L"C-09 a traversal path is passed through as data without rewriting");
    s.expect(escapeForReport("a\nb\tc\rd") == "a&#65533;b&#65533;c&#65533;d",
             L"C-09 newlines and tabs inside an untrusted field become replacement references");
    s.expect(escapeForReport("") == "",
             L"C-09 escaping an empty string yields an empty string");
    s.expect(escapeForReport("plain_module.sys") == "plain_module.sys",
             L"C-09 a harmless module name is left byte-for-byte alone");
    s.expect(escapeForReport("\xE4" "\xB8" "\xAD") == "\xE4" "\xB8" "\xAD",
             L"C-09 non-ASCII UTF-8 bytes pass through unchanged");
    {
        std::string withNul = "mod";
        withNul.push_back('\0');
        withNul += "ule";
        s.expect(escapeForReport(withNul) == "mod&#65533;ule",
                 L"C-09 an embedded NUL byte is neutralised without truncating the field");
    }

    // Plain-text report export: sanitize control characters only, without HTML escaping.
    s.expect(sanitizeForPlainTextField("mod\r\nule\tname") == "mod??ule?name",
             L"C-09 the plain-text field sanitiser replaces control characters so columns survive");
    s.expect(sanitizeForPlainTextField("<b>&amp;</b>") == "<b>&amp;</b>",
             L"C-09 the plain-text sanitiser does not HTML-escape, it is a separate exit");

    // Exit check: Each of these raw fragments triggers a risk.
    s.expect(classifyReportFragment("<script>x()</script>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a raw script tag is caught by the report exit check");
    s.expect(classifyReportFragment("<div onclick=\"x()\">") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 an inline event handler is caught by the report exit check");
    s.expect(classifyReportFragment("<a href=\"javascript:x()\">go</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a javascript: URL is caught by the report exit check");
    s.expect(classifyReportFragment("<exec cmd=\"!process 0 0\">run</exec>") ==
                 ReportOutputRisk::kDebuggerMarkupLink,
             L"C-09 a DML exec tag is caught by the report exit check");
    s.expect(classifyReportFragment("<link cmd=\".reload /f\">reload</link>") ==
                 ReportOutputRisk::kDebuggerMarkupLink,
             L"C-09 a DML link tag outranks its plain HTML resource meaning");
    s.expect(classifyReportFragment("<img src=\"http://evil.example/x.png\">") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 an external image tag is caught by the report exit check");
    s.expect(classifyReportFragment("<IMG SRC=HTTP://EVIL.EXAMPLE/X.PNG>") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 the exit check folds ASCII case, so uppercase tags do not slip through");
    s.expect(classifyReportFragment("<a href=\"https://evil.example/\">click</a>") ==
                 ReportOutputRisk::kExternalLink,
             L"C-09 an external hyperlink is caught by the report exit check");
    // The 'file:' branch and the '//' branch are two independent branches within the same OR chain. Originally, there was only one assertion
    // where the input 'file://server/share/x' matched the '//' branch first, causing the 'file:' branch to never execute (verified: removing
    // the 'file:' check leaves all assertions passing). This is split into two separate assertions to cover each branch independently.
    s.expect(classifyReportFragment("<a href=\"file:C:/dumps/x\">click</a>") ==
                 ReportOutputRisk::kExternalLink,
             L"C-09 a file: URL with no double slash is caught by the file: branch itself");
    s.expect(classifyReportFragment("<a href=\"file:C:\\dumps\\x\">click</a>") ==
                 ReportOutputRisk::kExternalLink,
             L"C-09 a backslash file: URL is caught by the file: branch too");
    s.expect(classifyReportFragment("<a href=\"file://server/share/x\">click</a>") ==
                 ReportOutputRisk::kExternalLink,
             L"C-09 a protocol-relative double slash in a link is caught by its own branch");

    // Four ways to automatically connect externally upon opening a report. All are unrelated to href/src, so the original
    // attribute threshold (only recognizing href and src) cannot block any of them — in practice, all four return Ok.
    s.expect(classifyReportFragment(
                 "<div style=\"background:url(https://evil.example/beacon.png)\">mod</div>") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 a CSS url() in a style attribute is an automatic external fetch");
    s.expect(classifyReportFragment("<style>@import url(http://evil.example/a.css);</style>") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 an @import inside a style element is an automatic external fetch");
    s.expect(classifyReportFragment(
                 "<table background=\"http://evil.example/beacon.png\"><tr><td>x</td></tr></table>") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 a legacy background attribute on a harmless tag is an automatic external fetch");
    s.expect(classifyReportFragment("<body background=\"//evil.example/beacon.png\">") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 a protocol-relative background attribute is an automatic external fetch");
    s.expect(classifyReportFragment("<video poster=\"https://evil.example/p.png\">") ==
                 ReportOutputRisk::kExternalResourceTag,
             L"C-09 a poster attribute is an automatic external fetch");
    s.expect(classifyReportFragment("<form action=\"https://evil.example/collect\">") ==
                 ReportOutputRisk::kExternalLink,
             L"C-09 a form action pointing outside is caught as an external link");

    // Browsers resolve character references before parsing attribute values as URLs, so comparing against the literal
    // "javascript:" is equivalent to no comparison at all. All three variants were observed to return Ok in practice.
    s.expect(classifyReportFragment("<a href=\"&#106;avascript:alert(1)\">click</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a decimal character reference cannot smuggle a javascript: URL past the exit check");
    s.expect(classifyReportFragment("<a href=\"&#x6a;avascript:alert(1)\">click</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a hex character reference cannot smuggle a javascript: URL either");
    s.expect(classifyReportFragment("<a href=\"javascript&colon;alert(1)\">click</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a named character reference for the colon cannot smuggle a javascript: URL");
    s.expect(classifyReportFragment(
                 "<a href=\"data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==\">x</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a data: URI is treated as script, not as harmless inline content");
    s.expect(classifyReportFragment("<a href=\"vbscript:msgbox(1)\">x</a>") ==
                 ReportOutputRisk::kScriptOrEventHandler,
             L"C-09 a vbscript: URL is caught alongside javascript:");
    // Folding applies only to the attribute region. Already-escaped safe text must not be folded back into tags to trigger an alert.
    s.expect(classifyReportFragment("&lt;a href=&quot;javascript:alert(1)&quot;&gt;x&lt;/a&gt;") ==
                 ReportOutputRisk::kOk,
             L"C-09 entity folding never resurrects tags from already-escaped safe text");
    s.expect(classifyReportFragment("<span title=\"crash at 10:24 &amp; module a&amp;b\">x</span>") ==
                 ReportOutputRisk::kOk,
             L"C-09 ordinary escaped ampersands in an attribute do not trip the folded scan");
    s.expect(classifyReportFragment("faulting module acme\x01_filter.sys") ==
                 ReportOutputRisk::kRawControlCharacter,
             L"C-09 a raw control character in the report is caught by the exit check");
    s.expect(classifyReportFragment("module acme_filter.sys + 0x1234\nnext line\tcolumn") ==
                 ReportOutputRisk::kOk,
             L"C-09 ordinary report text with layout whitespace passes the exit check");
    s.expect(classifyReportFragment("<a href=\"#local-anchor\">jump</a>") == ReportOutputRisk::kOk,
             L"C-09 a purely local anchor is not flagged as an external link");
    s.expect(classifyReportFragment("") == ReportOutputRisk::kOk,
             L"C-09 an empty fragment passes the exit check");

    // End-to-end: Any malicious external text, after escaping through the export, must no longer trigger export checks.
    {
        const char* const kEvilNames[] = {
            "<script>fetch('http://evil.example')</script>",
            "<img src=\"http://evil.example/beacon.png\">",
            "<exec cmd=\".shell del /f /q C:\\\">click</exec>",
            "<link cmd=\"!process 0 0\">x</link>",
            "acme\";shutdown -r -t 0 &",
            "..\\..\\..\\Windows\\System32\\drivers\\evil.sys",
            "a\nb\rc\td",
            "<a href=\"javascript:alert(1)\">x</a>",
            "<div onmouseover=alert(1)>",
            "CON",
            "'; DROP TABLE modules; --",
        };
        bool allSafe = true;
        bool allChanged = true;
        for (const char* const kEvil : kEvilNames) {
            const std::string kEscaped = escapeForReport(kEvil);
            allSafe = allSafe && classifyReportFragment(kEscaped) == ReportOutputRisk::kOk;
            // Only paths containing dangerous characters must be actually modified; pure paths do not contain &, <, >, ", ', or control characters.
            const std::string_view kOriginal(kEvil);
            const bool kNeedsChange =
                kOriginal.find_first_of("&<>\"'\n\r\t") != std::string_view::npos;
            allChanged = allChanged && (!kNeedsChange || kEscaped != kOriginal);
        }
        s.expect(allSafe,
                 L"C-09 every escaped untrusted name passes the report exit check");
        s.expect(allChanged,
                 L"C-09 escaping actually rewrites the dangerous inputs rather than passing them through");
    }

    // Whitelist self-audit: First use an independent scan to confirm the table itself is clean, then verify the predicate accepts it.
    {
        const std::span<const std::string_view> kCommands = allowedAnalysisCommands();
        s.expect(!kCommands.empty(), L"C-09 the analysis command whitelist is not empty");
        bool tableClean = true;
        for (const std::string_view kCommand : kCommands) {
            if (kCommand.empty() || kCommand.size() > 64U) {
                tableClean = false;
            }
            for (const char kRaw : kCommand) {
                const auto kByte = static_cast<unsigned char>(kRaw);
                const bool kStructural = kByte < 0x20U || kByte == 0x7FU || kByte == ';' ||
                                        kByte == '|' || kByte == '&' || kByte == '<' || kByte == '>' ||
                                        kByte == '$' || kByte == '`' || kByte == '"' || kByte == '\'' ||
                                        kByte == '\\' || kByte == '(' || kByte == ')' || kByte == '{' ||
                                        kByte == '}' || kByte == '[' || kByte == ']' || kByte == '!' ||
                                        kByte == '*' || kByte == '?' || kByte == '^' || kByte == '%';
                if (kStructural) {
                    tableClean = false;
                }
            }
        }
        s.expect(tableClean,
                 L"C-09 every whitelisted command is short and free of control and shell characters");
        bool allAccepted = true;
        for (const std::string_view kCommand : kCommands) {
            allAccepted = allAccepted && isSafeAnalysisCommand(kCommand) &&
                          classifyCommandRequest(kCommand) == CommandRejection::kAccepted;
        }
        s.expect(allAccepted,
                 L"C-09 the whitelist and the request classifier agree on every entry");
    }

    // Reject branches covered item by item.
    s.expect(classifyCommandRequest("") == CommandRejection::kEmpty,
             L"C-09 an empty analysis command is rejected as Empty");
    s.expect(classifyCommandRequest(std::string(200U, 'k')) == CommandRejection::kTooLong,
             L"C-09 an over-long analysis command is rejected as TooLong");
    s.expect(classifyCommandRequest("lm\nk") == CommandRejection::kContainsControlCharacter,
             L"C-09 a newline in an analysis command is rejected before anything else");
    s.expect(classifyCommandRequest(".bugcheck; .shell dir") ==
                 CommandRejection::kContainsShellMetacharacter,
             L"C-09 a chained shell command is rejected as a metacharacter");
    s.expect(classifyCommandRequest(".bugcheck && whoami") ==
                 CommandRejection::kContainsShellMetacharacter,
             L"C-09 an ampersand chain is rejected as a metacharacter");
    s.expect(classifyCommandRequest("!process 0 0") ==
                 CommandRejection::kContainsShellMetacharacter,
             L"C-09 an extension command with a bang prefix is rejected");
    s.expect(classifyCommandRequest("lmv") == CommandRejection::kNotInWhitelist,
             L"C-09 a near-miss command is rejected as not whitelisted");
    s.expect(classifyCommandRequest(".bugcheck ") == CommandRejection::kNotInWhitelist,
             L"C-09 a trailing space makes the command a non-member of the whitelist");
    s.expect(classifyCommandRequest("k v") == CommandRejection::kNotInWhitelist,
             L"C-09 adding an argument to a whitelisted command is rejected");
    s.expect(!isSafeAnalysisCommand(".BUGCHECK"),
             L"C-09 the whitelist match is exact, not case-folded");
    s.expect(!isSafeAnalysisCommand(""), L"C-09 the empty string is not a whitelisted command");
    s.expect(std::string(commandRejectionName(CommandRejection::kNotInWhitelist)) ==
                     "NotInWhitelist" &&
                 std::string(commandRejectionName(CommandRejection::kAccepted)) == "Accepted",
             L"C-09 command rejection reasons have distinct names");

    // Nine branches for path classification.
    s.expect(classifyDumpPath("C:\\Windows\\Minidump\\010124-12345-01.dmp") == PathRisk::kOk,
             L"C-09 a normal local dump path is Ok");
    s.expect(classifyDumpPath("") == PathRisk::kEmpty,
             L"C-09 an empty path is Empty");
    s.expect(classifyDumpPath(std::string(40000U, 'a')) == PathRisk::kTooLong,
             L"C-09 an absurdly long path is TooLong");
    s.expect(classifyDumpPath("C:\\dumps\\bad\nname.dmp") == PathRisk::kControlCharacter,
             L"C-09 a newline inside a path is caught");
    s.expect(classifyDumpPath("C:\\dumps\\*.dmp") == PathRisk::kWildCard,
             L"C-09 a wildcard path is not silently expanded");
    s.expect(classifyDumpPath("C:\\dumps\\..\\..\\Windows\\System32\\config") ==
                 PathRisk::kParentTraversal,
             L"C-09 a parent traversal segment is caught");
    s.expect(classifyDumpPath("C:\\dumps\\a.dmp:hidden") == PathRisk::kAlternateDataStream,
             L"C-09 an alternate data stream suffix is caught");
    s.expect(classifyDumpPath("C:\\dumps\\NUL.dmp") == PathRisk::kDeviceName,
             L"C-09 a reserved device name segment is caught even with an extension");
    s.expect(classifyDumpPath("C:\\dumps\\com1") == PathRisk::kDeviceName,
             L"C-09 a reserved COM device name is caught case-insensitively");
    s.expect(classifyDumpPath("\\\\server\\share\\crash.dmp") == PathRisk::kUncOrRemote,
             L"C-09 a UNC path is flagged as remote");
    s.expect(classifyDumpPath("//server/share/crash.dmp") == PathRisk::kUncOrRemote,
             L"C-09 a forward-slash UNC path is flagged as remote");
    s.expect(classifyDumpPath("dumps/sub/crash.dmp") == PathRisk::kOk,
             L"C-09 a relative path without traversal is Ok");

    // DOS device namespace. \\.\ is neither a remote path nor a file: previously it reached the end and was
    // treated as UncOrRemote, causing the UI to ask "Is this a remote path? Confirm?" (asking the wrong
    // question). After confirmation, it actually allowed opening. A local attacker could set up a named pipe
    // to impersonate a dump file, feeding the parser an infinite-length, variable, non-file byte stream.
    s.expect(classifyDumpPath("\\\\.\\PhysicalDrive0") == PathRisk::kDeviceName,
             L"C-09 the raw disk device namespace is a device name, not a remote path");
    s.expect(classifyDumpPath("\\\\.\\pipe\\evil") == PathRisk::kDeviceName,
             L"C-09 a named pipe in the device namespace is a device name, not a remote path");
    s.expect(classifyDumpPath("\\\\.\\C:") == PathRisk::kDeviceName,
             L"C-09 a volume opened through the device namespace is a device name");
    s.expect(classifyDumpPath("//./PhysicalDrive0") == PathRisk::kDeviceName,
             L"C-09 the forward-slash spelling of the device namespace is caught the same way");
    s.expect(classifyDumpPath("\\\\?\\GLOBALROOT\\Device\\HarddiskVolume1\\x.dmp") ==
                 PathRisk::kDeviceName,
             L"C-09 GLOBALROOT loops back into the device namespace and is caught there");
    s.expect(!pathAcceptableForOpen(classifyDumpPath("\\\\.\\PhysicalDrive0")) &&
                 !pathAcceptableForOpen(classifyDumpPath("\\\\.\\pipe\\evil")) &&
                 !pathAcceptableForOpen(classifyDumpPath("\\\\.\\C:")),
             L"C-09 red line: nothing in the device namespace is acceptable to open as a dump");

    // Win32 long path prefix. This is the only way to open dumps exceeding MAX_PATH. Previously, the '?' in the prefix
    // was blocked by wildcard scanners, causing legitimate long-path dumps to remain inaccessible due to incorrect logic.
    s.expect(classifyDumpPath("\\\\?\\C:\\Windows\\Minidump\\010124-12345-01.dmp") == PathRisk::kOk,
             L"C-09 a long-path-prefixed local dump is Ok, not a wildcard");
    s.expect(pathAcceptableForOpen(
                 classifyDumpPath("\\\\?\\C:\\Windows\\Minidump\\010124-12345-01.dmp")),
             L"C-09 a long-path-prefixed local dump can actually be opened");
    s.expect(classifyDumpPath("\\\\?\\UNC\\server\\share\\c.dmp") == PathRisk::kUncOrRemote,
             L"C-09 the long-path spelling of a UNC share is still a remote path");
    s.expect(pathNeedsExplicitConfirmation(classifyDumpPath("\\\\?\\UNC\\server\\share\\c.dmp")),
             L"C-09 a long-path UNC still needs explicit confirmation");
    // Stripping the prefix does not grant permission: the content after the prefix is still evaluated item by item.
    s.expect(classifyDumpPath("\\\\?\\C:\\dumps\\*.dmp") == PathRisk::kWildCard,
             L"C-09 a real wildcard behind the long-path prefix is still a wildcard");
    s.expect(classifyDumpPath("\\\\?\\C:\\dumps\\..\\..\\config") == PathRisk::kParentTraversal,
             L"C-09 a traversal behind the long-path prefix is still a traversal");
    s.expect(classifyDumpPath("\\\\?\\C:\\dumps\\NUL.dmp") == PathRisk::kDeviceName,
             L"C-09 a reserved device name behind the long-path prefix is still a device name");
    s.expect(classifyDumpPath("\\\\?\\") == PathRisk::kEmpty,
             L"C-09 a bare long-path prefix names nothing to open");
    // "//?/" is not a long-path prefix (that prefix's purpose is to disable path normalization, which only works
    // with backslashes), so the '?' inside must be treated as a wildcard. The failure direction is on the safe side.
    s.expect(classifyDumpPath("//?/C:/dumps/x.dmp") == PathRisk::kWildCard,
             L"C-09 the forward-slash spelling is not a long-path prefix and stays a wildcard");

    // Trailing '.' and ' ': Windows strips them when opening a file, so the string being classified
    // is not the same as the actual file opened, rendering the classification meaningless.
    s.expect(classifyDumpPath("C:\\dumps\\crash.dmp.") == PathRisk::kTrailingDotOrSpace,
             L"C-09 a trailing dot is refused because Windows would strip it before opening");
    s.expect(classifyDumpPath("C:\\dumps\\crash.dmp ") == PathRisk::kTrailingDotOrSpace,
             L"C-09 a trailing space is refused for the same reason");
    s.expect(classifyDumpPath("C:\\dumps \\crash.dmp") == PathRisk::kTrailingDotOrSpace,
             L"C-09 a trailing space on an intermediate segment is refused too");
    s.expect(!pathAcceptableForOpen(PathRisk::kTrailingDotOrSpace),
             L"C-09 a path whose text does not name the file that would be opened is not opened");
    s.expect(classifyDumpPath(".\\crash.dmp") == PathRisk::kOk &&
                 classifyDumpPath("C:\\dumps\\.\\crash.dmp") == PathRisk::kOk,
             L"C-09 a current-directory segment is path syntax, not a trailing-dot problem");

    s.expect(pathAcceptableForOpen(PathRisk::kOk) && pathAcceptableForOpen(PathRisk::kUncOrRemote),
             L"C-09 only ordinary and UNC paths are acceptable to open");
    s.expect(!pathAcceptableForOpen(PathRisk::kParentTraversal) &&
                 !pathAcceptableForOpen(PathRisk::kDeviceName) &&
                 !pathAcceptableForOpen(PathRisk::kAlternateDataStream) &&
                 !pathAcceptableForOpen(PathRisk::kWildCard) &&
                 !pathAcceptableForOpen(PathRisk::kControlCharacter) &&
                 !pathAcceptableForOpen(PathRisk::kTrailingDotOrSpace) &&
                 !pathAcceptableForOpen(PathRisk::kTooLong) &&
                 !pathAcceptableForOpen(PathRisk::kEmpty),
             L"C-09 every risky path class is refused for opening");
    s.expect(pathNeedsExplicitConfirmation(PathRisk::kUncOrRemote) &&
                 !pathNeedsExplicitConfirmation(PathRisk::kOk),
             L"C-09 only a remote path additionally needs explicit confirmation");
    s.expect(std::string(pathRiskName(PathRisk::kAlternateDataStream)) == "AlternateDataStream" &&
                 std::string(pathRiskName(PathRisk::kParentTraversal)) == "ParentTraversal" &&
                 std::string(pathRiskName(PathRisk::kDeviceName)) == "DeviceName" &&
                 std::string(pathRiskName(PathRisk::kTrailingDotOrSpace)) == "TrailingDotOrSpace",
             L"C-09 path risks have distinct names");
    s.expect(std::string(reportOutputRiskName(ReportOutputRisk::kDebuggerMarkupLink)) ==
                     "DebuggerMarkupLink" &&
                 std::string(reportOutputRiskName(ReportOutputRisk::kExternalResourceTag)) ==
                     "ExternalResourceTag" &&
                 std::string(reportOutputRiskName(ReportOutputRisk::kRawControlCharacter)) ==
                     "RawControlCharacter" &&
                 std::string(reportOutputRiskName(ReportOutputRisk::kExternalLink)) ==
                     "ExternalLink" &&
                 std::string(reportOutputRiskName(ReportOutputRisk::kOk)) == "Ok",
             L"C-09 report output risks have distinct names");
}

// ---------------------------------------------------------------------------
// C-10 Report provenance
// ---------------------------------------------------------------------------
DumpReportProvenance makeCompleteProvenance() {
    DumpReportProvenance provenance;
    provenance.engine.engineId = "ksword.dumpfacts";
    provenance.engine.engineVersion = "1.0.0";
    provenance.engine.engineAvailable = true;
    provenance.input.filePath = "C:\\Windows\\Minidump\\010124-12345-01.dmp";
    provenance.input.fileSize = OptionalU64::of(0x50000ULL);
    provenance.input.sha256Hex =
        "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
    provenance.input.hashComputed = true;
    provenance.input.lastModifiedUtc100ns = OptionalU64::of(133000000000000000ULL);
    provenance.source.collectorId = "offline.dump.facts";
    provenance.source.collectorVersion = 1U;
    provenance.source.sourceGroup = "offline-sample";
    provenance.source.origin = SourceOrigin::kOfflineSample;
    provenance.window.startUtc100ns = OptionalU64::of(133100000000000000ULL);
    provenance.window.endUtc100ns = OptionalU64::of(133100000012000000ULL);
    provenance.window.mode = CaptureMode::kReplay;
    provenance.analysisScope.totalKnown = OptionalU64::of(42ULL);
    provenance.analysisScope.succeeded = 42U;

    ModuleSymbolState matched;
    matched.moduleName = "ntoskrnl.exe";
    matched.match = SymbolMatch::kMatched;
    matched.attempt = SymbolLoadAttempt::kFileLoaded;
    matched.cacheSource = SymbolCacheSource::kLocalCache;
    provenance.symbolStates.push_back(matched);

    ModuleSymbolState wrong;
    wrong.moduleName = "acme_filter.sys";
    wrong.match = SymbolMatch::kWrongVersion;
    wrong.attempt = SymbolLoadAttempt::kFileLoaded;
    provenance.symbolStates.push_back(wrong);

    ModuleSymbolState absent;
    absent.moduleName = "mystery.sys";
    absent.match = SymbolMatch::kAbsent;
    absent.attempt = SymbolLoadAttempt::kFileNotFound;
    provenance.symbolStates.push_back(absent);

    provenance.availability = deriveAvailabilityFromKind(DumpKind::kKernelSmall);
    return provenance;
}

bool hasGap(const std::vector<ProvenanceGap>& gaps, ProvenanceGap wanted) {
    for (const ProvenanceGap kGap : gaps) {
        if (kGap == wanted) {
            return true;
        }
    }
    return false;
}

std::string fieldValue(const std::vector<ReportField>& fields, const std::string& key) {
    for (const ReportField& field : fields) {
        if (field.key == key) {
            return field.value;
        }
    }
    return std::string("<<missing key>>");
}

void testProvenance(Reporter& s) {
    // Default construction: non-redundant kernel, with gaps listed item by item.
    {
        const DumpReportProvenance kFresh;
        const std::vector<ProvenanceGap> kGaps = auditProvenance(kFresh);
        s.expect(!provenanceReviewable(kFresh),
                 L"C-10 a default-constructed report provenance is not reviewable");
        s.expect(kGaps.size() == 9U,
                 L"C-10 the default provenance reports exactly the nine missing items");
        s.expect(hasGap(kGaps, ProvenanceGap::kMissingEngineIdentity) &&
                     hasGap(kGaps, ProvenanceGap::kMissingEngineVersion) &&
                     hasGap(kGaps, ProvenanceGap::kMissingInputPath) &&
                     hasGap(kGaps, ProvenanceGap::kMissingInputSize) &&
                     hasGap(kGaps, ProvenanceGap::kMissingInputHash) &&
                     hasGap(kGaps, ProvenanceGap::kMissingAnalysisWindow) &&
                     hasGap(kGaps, ProvenanceGap::kMissingSymbolStates) &&
                     hasGap(kGaps, ProvenanceGap::kUnstatedAnalysisScope) &&
                     hasGap(kGaps, ProvenanceGap::kWrongSourceOrigin),
                 L"C-10 every default gap is named individually rather than as one failure");
        s.expect(!hasGap(kGaps, ProvenanceGap::kUndisclosedExternalSupplement),
                 L"C-10 not using an external supplement is not itself a gap");
    }

    // Complete provenance: reviewable.
    const DumpReportProvenance kComplete = makeCompleteProvenance();
    s.expect(auditProvenance(kComplete).empty() && provenanceReviewable(kComplete),
             L"C-10 a complete provenance has no gaps and is reviewable");

    // Remove items individually; each generates only its corresponding missing entry.
    {
        DumpReportProvenance missing = kComplete;
        missing.engine.engineVersion.clear();
        const std::vector<ProvenanceGap> kGaps = auditProvenance(missing);
        s.expect(kGaps.size() == 1U && kGaps[0] == ProvenanceGap::kMissingEngineVersion,
                 L"C-10 dropping the engine version yields exactly that gap");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.input.hashComputed = false;
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingInputHash,
                 L"C-10 an uncomputed input hash is reported as a gap, not as a zero hash");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.input.sha256Hex = "0123";
        s.expect(hasGap(auditProvenance(missing), ProvenanceGap::kMissingInputHash),
                 L"C-10 a malformed hash string does not pass as an input identity");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.input.fileSize = OptionalU64::unset();
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingInputSize,
                 L"C-10 an unknown input size is a gap, never a reported zero");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.window.endUtc100ns = OptionalU64::unset();
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingAnalysisWindow,
                 L"C-10 a half-open analysis window counts as missing");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.symbolStates.clear();
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingSymbolStates,
                 L"C-10 a report without symbol status cannot be re-reviewed");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.analysisScope = CoverageAccount{};
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kUnstatedAnalysisScope,
                 L"C-10 an empty coverage account does not count as a stated analysis scope");
    }
    {
        DumpReportProvenance wrong = kComplete;
        wrong.source.origin = SourceOrigin::kLiveKernel;
        s.expect(auditProvenance(wrong).size() == 1U &&
                     auditProvenance(wrong)[0] == ProvenanceGap::kWrongSourceOrigin,
                 L"C-10 an offline dump report must be labelled as an offline sample");
    }
    {
        DumpReportProvenance supplemented = kComplete;
        supplemented.supplement.used = true;
        s.expect(auditProvenance(supplemented).size() == 1U &&
                     auditProvenance(supplemented)[0] ==
                         ProvenanceGap::kUndisclosedExternalSupplement,
                 L"C-10 using data from outside the dump without disclosing it is a gap");
        supplemented.supplement.disclosureKey = "dump.supplement.disk_image";
        supplemented.supplement.source.collectorId = "disk.image.reader";
        supplemented.supplement.source.origin = SourceOrigin::kExternalFile;
        s.expect(auditProvenance(supplemented).empty(),
                 L"C-10 a disclosed external supplement closes the gap");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.engine.engineId.clear();
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingEngineIdentity,
                 L"C-10 dropping the engine id yields exactly that gap");
    }
    {
        DumpReportProvenance missing = kComplete;
        missing.input.filePath.clear();
        s.expect(auditProvenance(missing).size() == 1U &&
                     auditProvenance(missing)[0] == ProvenanceGap::kMissingInputPath,
                 L"C-10 dropping the input path yields exactly that gap");
    }

    // Report fields: escape external text uniformly; use a fixed placeholder key for missing values.
    {
        DumpReportProvenance evil = kComplete;
        evil.input.filePath = "C:\\dumps\\<img src=\"http://evil.example/x\">.dmp";
        evil.engine.engineVersion = "1.0 & \"beta\"";
        const std::vector<ReportField> kFields = buildProvenanceFields(evil);
        s.expect(fieldValue(kFields, "dump.report.input_path") ==
                     "C:\\dumps\\&lt;img src=&quot;http://evil.example/x&quot;&gt;.dmp",
                 L"C-10 the report path field is escaped byte-for-byte as expected");
        s.expect(fieldValue(kFields, "dump.report.engine_version") == "1.0 &amp; &quot;beta&quot;",
                 L"C-10 the engine version field is escaped too");
        bool allSafe = true;
        for (const ReportField& field : kFields) {
            allSafe = allSafe && classifyReportFragment(field.value) == ReportOutputRisk::kOk;
        }
        s.expect(allSafe,
                 L"C-09 every generated report field passes the report exit check");
        s.expect(fieldValue(kFields, "dump.report.symbol_module_count") == "3" &&
                     fieldValue(kFields, "dump.report.symbol_matched_count") == "1" &&
                     fieldValue(kFields, "dump.report.symbol_wrong_version_count") == "1" &&
                     fieldValue(kFields, "dump.report.symbol_absent_count") == "1" &&
                     fieldValue(kFields, "dump.report.symbol_not_attempted_count") == "0",
                 L"C-10 the report states the symbol status breakdown so it can be re-reviewed");
        s.expect(fieldValue(kFields, "dump.report.input_size") == "327680",
                 L"C-10 the input size is written as an exact decimal, not a rounded value");
        s.expect(fieldValue(kFields, "dump.report.source_origin") == "OfflineSample",
                 L"C-10 the report names the source origin explicitly");
        s.expect(fieldValue(kFields, "dump.report.external_supplement") == "none",
                 L"C-10 the report states that no external supplement was used");
    }
    {
        const std::vector<ReportField> kFields = buildProvenanceFields(DumpReportProvenance{});
        s.expect(fieldValue(kFields, "dump.report.input_size") == "dump.value.unknown",
                 L"C-10 an unknown input size renders as the unknown key, never as 0");
        s.expect(fieldValue(kFields, "dump.report.input_sha256") == "dump.value.unknown",
                 L"C-10 an uncomputed hash renders as the unknown key, never as an empty string");
        s.expect(fieldValue(kFields, "dump.report.analysis_window_start") == "dump.value.unknown" &&
                     fieldValue(kFields, "dump.report.analysis_window_end") == "dump.value.unknown",
                 L"C-10 an unknown analysis window renders as the unknown key");
        s.expect(fieldValue(kFields, "dump.report.engine_available") == "false",
                 L"C-10 engine availability defaults to false in the report");
        s.expect(fieldValue(kFields, "dump.report.analysis_scope_remaining") == "remaining:unknown",
                 L"C-10 an unstated scope reports its remainder as unknown, not as zero");
    }

    s.expect(std::string(provenanceGapName(ProvenanceGap::kUndisclosedExternalSupplement)) ==
                     "UndisclosedExternalSupplement" &&
                 std::string(provenanceGapName(ProvenanceGap::kUnstatedAnalysisScope)) ==
                     "UnstatedAnalysisScope" &&
                 std::string(provenanceGapName(ProvenanceGap::kMissingInputHash)) ==
                     "MissingInputHash",
             L"C-10 provenance gaps have distinct names");
}

// ---------------------------------------------------------------------------
// Performance guard: Previous measurements recorded O(n^2) at 15s and 13s.
// Here, hard limits are set for the three paths that consume large inputs.
// ---------------------------------------------------------------------------
void testPerformanceGuards(Reporter& s) {
    using Clock = std::chrono::steady_clock;

    // 1) Validate 100,000 stack frames.
    {
        StackTrace trace;
        trace.frames.reserve(100000U);
        for (std::uint64_t index = 0; index < 100000U; ++index) {
            StackFrame frame;
            frame.address = OptionalU64::of(0xFFFFF80300000000ULL + index * 0x40ULL);
            frame.moduleName = "acme_filter.sys";
            frame.unwindState = UnwindState::kUnwound;
            frame.availableArgs.push_back(OptionalU64::of(index));
            trace.frames.push_back(std::move(frame));
        }
        const Clock::time_point kBegin = Clock::now();
        const StackValidation kVerdict = validateStackTrace(trace);
        const std::size_t kUnwound = trace.unwoundCount();
        const auto kElapsedMs =
            std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now() - kBegin).count();
        s.expect(kVerdict == StackValidation::kOk && kUnwound == 100000U,
                 L"C-05 a hundred-thousand-frame stack still validates correctly");
        s.expect(kElapsedMs < 2000,
                 L"C-05 validating a hundred thousand frames stays well under two seconds");
    }

    // 2) Groups 100,000 module evidence items (500 distinct module names).
    {
        std::vector<ModuleEvidenceItem> items;
        items.reserve(100000U);
        for (std::uint64_t index = 0; index < 100000U; ++index) {
            ModuleEvidenceItem item;
            item.kind = ModuleEvidenceKind::kOnStack;
            item.moduleName = "drv_" + std::to_string(index % 500U) + ".sys";
            item.frameUnwindState = UnwindState::kUnwound;
            item.frameIndex = OptionalU64::of(index);
            items.push_back(std::move(item));
        }
        const Clock::time_point kBegin = Clock::now();
        const std::vector<ModuleEvidenceGroup> kGroups = groupModuleEvidence(std::move(items));
        const auto kElapsedMs =
            std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now() - kBegin).count();
        s.expect(kGroups.size() == 500U,
                 L"C-06 grouping a hundred thousand evidence items yields the five hundred modules");
        std::size_t total = 0;
        for (const ModuleEvidenceGroup& group : kGroups) {
            total += group.evidenceCount();
        }
        s.expect(total == 100000U,
                 L"C-06 grouping keeps every evidence item exactly once");
        s.expect(kElapsedMs < 3000,
                 L"C-06 grouping a hundred thousand evidence items stays under three seconds");
    }

    // 3) 256 KiB external text undergoes escaping and exit checks.
    {
        std::string huge;
        huge.reserve(256U * 1024U);
        while (huge.size() < 256U * 1024U) {
            huge += "<a href=\"http://evil.example\">module&name</a>\t";
        }
        const Clock::time_point kBegin = Clock::now();
        const std::string kEscaped = escapeForReport(huge);
        const ReportOutputRisk kRisk = classifyReportFragment(kEscaped);
        const auto kElapsedMs =
            std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now() - kBegin).count();
        s.expect(kRisk == ReportOutputRisk::kOk,
                 L"C-09 a quarter-megabyte of hostile text is fully neutralised");
        s.expect(kEscaped.size() > huge.size(),
                 L"C-09 escaping a hostile blob actually expands it, proving it did work");
        s.expect(kElapsedMs < 2000,
                 L"C-09 escaping and checking a quarter-megabyte stays under two seconds");
        // The original (unescaped) text must be blocked by the exit check — otherwise the above 'pass' is meaningless.
        s.expect(classifyReportFragment(huge) != ReportOutputRisk::kOk,
                 L"C-09 the same blob before escaping is rejected by the exit check");
    }
}

} // namespace

int runDumpFactsTests() {
    ksword_tests::Suite suite(L"C offline dump facts");
    Reporter reporter(suite);
    testRecognition(reporter);
    testBugCheckFacts(reporter);
    testSymbolMatching(reporter);
    testStackAndUnwind(reporter);
    testSuspectExplanation(reporter);
    testContentAvailability(reporter);
    testInterruptionAndHelpers(reporter);
    testUntrustedTextAndCommands(reporter);
    testProvenance(reporter);
    testPerformanceGuards(reporter);
    suite.report();
    return suite.failures();
}
